local ffi = require("ffi")
local units = require("skills_unleashed.lib.units")

local M = {}

-- cube::GameController
local GC_PLAYER = 0x8006D0
local GC_CAMERA = 0x140                                        -- camera_position: the camera's eye, three int64 in world units
local KEY_M1, KEY_M2 = 4, 5                                    -- the key bytes of the two mouse buttons
local BAR_CONTROLLER = 0x10                                    -- [ESP+0x10] at the bar site: the game controller
local SAVE_PLAYER = 0x0C                                       -- [EBP+0xC] at the save site: the player the copy was made of
-- cube::Creature (offsets already shifted by +0x10)
local C_ID, C_MODE = 0x08, 0x68
local C_CHARGED, C_SPENT = 0x144, 0x13B4
local SLOT_LEFT, SLOT_RIGHT, ITEM_SIZE = 0x990, 0xAA8, 0x118
-- the bags (cube::Inventory at +0x11DC: a vector of up to four vectors of slots, each a count then the item) and the item on the
-- mouse cursor (its count at +0x11E8, the item at +0x11EC): mapping/types/core.toml
local INV_TABS, HELD_COUNT, HELD_ITEM = 0x11DC, 0x11E8, 0x11EC
local TAB_SIZE, BAG_SLOT, BAG_ITEM = 0x0C, 0x11C, 0x04
local MAX_TABS, MAX_BAG_SLOTS = 8, 4096                        -- bounds against a vector that reads wrong
-- cube::ItemData
local I_TYPE, I_SUB, I_MARK, I_LEVEL = 0x00, 0x01, 0x08, 0x10  -- I_MARK is minus_modifier
local TYPE_WEAPON, SUB_BOW = 3, 6
local CUB_HEADER, WHITE = 12, string.char(255, 255, 255)      -- a .cub: three uint32 sizes, then one RGB triple per voxel
local EMPTY = string.char(0, 0, 0)
local MARK = 0x4C49                                            -- what a bow of the mod carries in minus_modifier
local MODE_CHARGE, MODE_SHOT = 25, 23                          -- a bow's held charge; the one-arrow shot
-- cube::Projectile
local PR_OWNER, PR_POS, PR_VEL, PR_SKILL, PR_KIND, PR_AGE = 0x00, 0x18, 0x3C, 0x5C, 0x60, 0x68
local KIND_ARROW, KIND_STRAIGHT = 0, 1
local SHOT_CREATURE, SHOT_PROJECTILE = 0x2B14, 0x578           -- below EBP at the shot site
local STOP_FLAG = 0x2B58                                       -- below EBP at the stop site
-- the game's sound of the charge: a sound action (the position, the sound id at +0xC, pitch +0x10, volume +0x14)
local CHARGE_SOUND, SOUND_VOLUME = 0x740, 0x14                 -- below EBP at the charge sound's site; its volume

M.MARK = MARK
M.offsets = { mode = C_MODE, charged = C_CHARGED, spent = C_SPENT, slot_left = SLOT_LEFT, slot_right = SLOT_RIGHT, item_size = ITEM_SIZE, item_mark = I_MARK,
  item_level = I_LEVEL, gc_player = GC_PLAYER, gc_camera = GC_CAMERA, save_player = SAVE_PLAYER, proj_pos = PR_POS,
  proj_vel = PR_VEL, proj_skill = PR_SKILL, proj_kind = PR_KIND, proj_age = PR_AGE, shot_creature = SHOT_CREATURE,
  shot_projectile = SHOT_PROJECTILE, stop_flag = STOP_FLAG, inv_tabs = INV_TABS, held_count = HELD_COUNT, held_item = HELD_ITEM,
  bag_slot = BAG_SLOT, bag_item = BAG_ITEM, charge_sound = CHARGE_SOUND, sound_volume = SOUND_VOLUME }
M.MODE_CHARGE, M.MODE_SHOT = MODE_CHARGE, MODE_SHOT

local function u8(a) return ffi.cast("uint8_t*", a)[0] end
local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function f32(a) return ffi.cast("float*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_u8(a, v) ffi.cast("uint8_t*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end
local function put_f32(a, v) ffi.cast("float*", a)[0] = v end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: bow: " .. text) end
end

local function guarded(name, fn)
  return function(ctx)
    local ok, e = pcall(fn, ctx)
    if not ok then warn_once("run:" .. name .. tostring(e), name .. ": " .. tostring(e)) end
  end
end

local function controller()
  local at = kyubu.symbol("cube::game_controller")
  return at and u32(at) or 0
end

local function local_player()
  local gc = controller()
  return gc ~= 0 and u32(gc + GC_PLAYER) or 0
end
M.local_player = local_player

-- The camera's eye in blocks (x, y, z), or nil outside a game. The crosshair's ray runs from it through the player's aim.
function M.camera()
  local gc = controller()
  if gc == 0 then return nil end
  return units.to_blocks(i64(gc + GC_CAMERA)), units.to_blocks(i64(gc + GC_CAMERA + 8)), units.to_blocks(i64(gc + GC_CAMERA + 16))
end

-- ---- what the creature is doing ------------------------------------------------------------------------------------------

function M.mode(c) return u8(c + C_MODE) end
function M.is_charging(c) return u8(c + C_MODE) == MODE_CHARGE end
function M.is_shooting(c) return u8(c + C_MODE) == MODE_SHOT end
-- The mp gathered by the held charge (0 to 1, at most the creature's mp).
function M.charged(c) return f32(c + C_CHARGED) end

-- ---- the swap ------------------------------------------------------------------------------------------------------------

local handlers = nil            -- what install() was given
local site_ok = {}              -- the sites install() put a hook on, by name
local swap = nil                -- { player =, at = the item's address, sub =, mark =, whole = the 0x118 bytes of an empty slot or nil }
local last_swap = nil           -- the last swap made: a save's copy that still carries the mark is put right from it
local model_id, model_slot = nil, nil
local get_model = nil           -- ModelLoader::get(this, slot) -> Model*, thiscall
local loader = nil              -- the ModelLoader, as the game hands it to its own itemModel
local item_hook = nil
local SAVE_SITE = "cube::GameController::saveCopiedSite"

-- The model a marked item is drawn with: the id given to kyubu.model.add. Its table slot is read when it is first needed, and
-- again in each world (a world's id map renumbers the slots when it is entered).
function M.set_bow_model(id) model_id = id; model_slot = nil end

local function bow_slot()
  if model_slot == nil and model_id and kyubu.model and kyubu.model.slot then model_slot = kyubu.model.slot(model_id) end
  return model_slot
end

local function is_marked(at)
  return u8(at + I_TYPE) == TYPE_WEAPON and u8(at + I_SUB) == SUB_BOW and i32(at + I_MARK) == MARK
end
M.is_marked = is_marked

-- Makes the item at `at` a bow of the mod: an item that is a weapon keeps everything but its sub_type and the mark; an empty
-- slot becomes a level 1 bow.
local function mark(at, was_weapon)
  if not was_weapon then
    ffi.fill(ffi.cast("void*", at), ITEM_SIZE)
    put_u8(at + I_TYPE, TYPE_WEAPON)
    put_i32(at + I_LEVEL, 1)
  end
  put_u8(at + I_SUB, SUB_BOW)
  put_i32(at + I_MARK, MARK)
end

-- Writes the item swap `s` replaced back at `at`: the player's own slot, or the same slot of a copy of the player.
local function unmark(at, s)
  if s.whole then
    ffi.copy(ffi.cast("void*", at), s.whole, ITEM_SIZE)
  else
    put_u8(at + I_SUB, s.sub)
    put_i32(at + I_MARK, s.mark)
  end
end

local function on_item_model(next, this, item)
  loader = this
  local a = tonumber(ffi.cast("uint32_t", item))
  if a ~= 0 and get_model and u8(a + I_TYPE) == TYPE_WEAPON and i32(a + I_MARK) == MARK then
    local slot = bow_slot()
    if slot then return get_model(this, slot) end
  end
  return next(this, item)
end
M._on_item_model = on_item_model                -- for the unit test

-- cube::GameController::saveCopiedSite: the game has copied the player (EBX) and is about to write the copy. A copy that carries
-- the mark gets the real item, so the save never holds the bow; the player in the game is not touched. The save itself is not
-- detoured: the autosave runs on a worker thread and takes the World's lock (see the head of this file).
local function on_save_copy(ctx)
  local s = swap or last_swap
  local copy = ctx.ebx
  if not s or copy == 0 then return end
  if swap and u32(ctx.ebp + SAVE_PLAYER) ~= s.player then return end
  local at = copy + (s.at - s.player)
  if is_marked(at) then unmark(at, s) end
end

-- A marked item (the bow in the hand) is drawn with the mod's model. Returns true when it is.
function M.look_on()
  if item_hook then return true end
  local g = kyubu.symbol("ModelLoader::get")
  if not g then
    warn_once("get-symbol", "ModelLoader::get has no symbol: the bow and the arrow have the game's look")
    return false
  end
  get_model = ffi.cast("void*(__thiscall*)(void*, int32_t)", g)
  local id, err = kyubu.hook("ModelLoader::itemModel", "void*(__thiscall*)(void*, void*)", on_item_model)
  if id then item_hook = id else warn_once("item", "ModelLoader::itemModel: the hook failed (" .. tostring(err) .. "): the bow has the game's look") end
  return item_hook ~= nil
end

-- Puts the bow in the player's hand: the right weapon when there is one, else the left, else a new item in the right slot.
-- Returns true, or false and the reason (without the save's site nothing is swapped: a save would keep the bow).
function M.swap_on(player)
  if swap then return swap.player == player end
  if not site_ok[SAVE_SITE] then return false, "no save guard" end
  local at = player + SLOT_RIGHT
  local was_weapon = u8(at + I_TYPE) == TYPE_WEAPON
  if not was_weapon and u8(player + SLOT_LEFT + I_TYPE) == TYPE_WEAPON then
    at = player + SLOT_LEFT
    was_weapon = true
  end
  local s = { player = player, at = at, sub = u8(at + I_SUB), mark = i32(at + I_MARK) }
  if not was_weapon then
    s.whole = ffi.new("uint8_t[?]", ITEM_SIZE)
    ffi.copy(s.whole, ffi.cast("void*", at), ITEM_SIZE)
  end
  mark(at, was_weapon)
  swap, last_swap = s, s
  return true
end

-- Calls fn(item, count) for every item creature `c` carries outside its equipment: the one on the mouse cursor and those in its
-- bags (`count` is the address of the slot's count word). Vectors that read wrong are skipped.
local function each_carried(c, fn)
  fn(c + HELD_ITEM, c + HELD_COUNT)
  local first, last = u32(c + INV_TABS), u32(c + INV_TABS + 4)
  if first == 0 or last < first or (last - first) % TAB_SIZE ~= 0 or (last - first) / TAB_SIZE > MAX_TABS then return end
  for tab = first, last - TAB_SIZE, TAB_SIZE do
    local s0, s1 = u32(tab), u32(tab + 4)
    if s0 ~= 0 and s1 >= s0 and (s1 - s0) % BAG_SLOT == 0 and (s1 - s0) / BAG_SLOT <= MAX_BAG_SLOTS then
      for slot = s0, s1 - BAG_SLOT, BAG_SLOT do fn(slot + BAG_ITEM, slot) end
    end
  end
end

-- Puts right every item of creature `c` that carries the mark, from what swap `s` replaced: its two weapon slots, the cursor and
-- the bags. A bow that was made from an empty hand is taken away (its slot emptied). Returns the places put right ("right",
-- "left", "cursor", "bag"), in that order.
local function repair_marked(c, s)
  local fixed = {}
  local function fix(at, count, where)
    if not is_marked(at) then return end
    unmark(at, s)
    if s.whole and count then put_i32(count, 0) end
    fixed[#fixed + 1] = where
  end
  fix(c + SLOT_RIGHT, nil, "right")
  fix(c + SLOT_LEFT, nil, "left")
  each_carried(c, function(at, count) fix(at, count, count == c + HELD_COUNT and "cursor" or "bag") end)
  return fixed
end

-- Puts the player's own weapon back. A bow that left its slot after all (the lock below keeps the clicks off it) is put right
-- where it is now. When it is nowhere, the item was replaced by other means: nothing is written and false is returned.
-- `player` must be the creature the swap was made on, and alive in memory.
function M.swap_off(player)
  local s = swap
  swap = nil
  if not s then return true end
  if s.player ~= player then return false, "another creature" end
  if is_marked(s.at) then
    unmark(s.at, s)
    return true
  end
  local fixed = repair_marked(player, s)
  if #fixed > 0 then
    warn_once("left", "the bow of light had left its slot: put right in " .. table.concat(fixed, ", "))
    return true
  end
  warn_once("moved", "the bow of light was moved out of its slot while it was held, and is not on the player any more")
  return false, "moved"
end

-- The safety net once the bow is gone: a marked item still on creature `c` (the slots, the cursor, the bags) is put right from the
-- last swap. Returns the places put right, an empty list when there was nothing (or no swap was ever made, or one is on).
function M.repair(c)
  if swap or not last_swap or not c or c == 0 then return {} end
  return repair_marked(c, last_swap)
end

-- cube::GameController::equipmentSlotUnderCursor: the slot under the mouse, where every click that takes an equipped item out
-- starts (a right click sends it to the bags, a left click swaps it with the cursor's item, a left click on the left hand bags a
-- two-handed right weapon). While the bow is in the hand neither weapon slot is under the mouse for the game, so those clicks do
-- nothing there and the bow cannot leave the hand. The hover box of the two slots is gone for that time as well.
local function on_slot_under_cursor(next, this)
  local slot = next(this)
  local s = swap
  if s and slot ~= nil then
    local a = tonumber(ffi.cast("uint32_t", slot))
    if a == s.player + SLOT_RIGHT or a == s.player + SLOT_LEFT then return nil end
  end
  return slot
end
M._on_slot_under_cursor = on_slot_under_cursor  -- for the unit test

function M.is_swapped() return swap ~= nil end

-- Drops the swap without a write: the world was left, the creature's memory is no longer the mod's to touch. What the swap
-- replaced is kept for the save that the game makes on the way out.
function M.forget()
  swap = nil
  model_slot = nil
  M._flight_reset()
end

-- ---- the white models ---------------------------------------------------------------------------------------------------

-- A .cub model with every voxel pure white (an empty one stays empty), or nil when `cub` is not a model.
function M.white_copy(cub)
  if type(cub) ~= "string" or #cub <= CUB_HEADER or (#cub - CUB_HEADER) % #WHITE ~= 0 then return nil end
  local body = cub:sub(CUB_HEADER + 1):gsub("...", function(v)
    if v == EMPTY then return v end
    return WHITE
  end)
  return cub:sub(1, CUB_HEADER) .. body
end

-- Serves the model key `key` (the file name given to kyubu.model.add) as a white copy of the first of the game's own models
-- `sources` that can be read. Call it in lifecycle.preinit: the game loads its models right after. Returns true when the
-- provider is in place.
function M.provide_white(key, sources)
  if not (kyubu.assets and kyubu.assets.provider and kyubu.assets.read) then
    warn_once("assets", "this Kyubu has no asset providers: the arrow has the game's look")
    return false
  end
  local ok, id, err = pcall(kyubu.assets.provider, "data1.db", key, function()
    for _, name in ipairs(sources) do
      local rok, data = pcall(kyubu.assets.read, "data1.db", name)
      local white = rok and M.white_copy(data) or nil
      if white then return white end
    end
    warn_once("source:" .. key, key .. ": none of the game's models could be read: the placeholder is drawn")
    return nil
  end)
  if not ok or not id then
    warn_once("provider:" .. key, key .. ": no provider (" .. tostring(ok and err or id) .. ")")
    return false
  end
  return true
end

-- ---- the charge's sound -------------------------------------------------------------------------------------------------

-- cube::World::chargeSoundSite: the game queues its charge sound (charge2.wav, pitch 1 + 0.5 * charged mp) for a creature that
-- holds a charge, once in each 200 ms of the hold. For the player who may charge the bow of the mod it is queued at volume 0:
-- the ability's own sound follows the charge instead (otherwise both are heard at once). Every other creature's is the game's.
local function on_charge_sound(ctx)
  local c = ctx.esi
  if c == 0 or not handlers.armed(c) then return end
  put_f32(ctx.ebp - CHARGE_SOUND + SOUND_VOLUME, 0)
end

-- ---- the arrow -----------------------------------------------------------------------------------------------------------

local arrow = nil               -- the arrow in flight: { hit = { [creature id] = true }, age =, ms =, ended = }
local current = nil             -- the address of the arrow while the World's loop is on it
local drawn = nil               -- the arrow whose draw is on (its kind is 0 for it)
local arrow_model_id, arrow_slot = nil, nil
local released = 0              -- the charge read at the release

function M.set_arrow_model(id) arrow_model_id = id; arrow_slot = nil end

local function arrow_model()
  if arrow_slot == nil and arrow_model_id and kyubu.model and kyubu.model.slot then arrow_slot = kyubu.model.slot(arrow_model_id) end
  return arrow_slot
end

local function is_ours(proj)
  if not arrow or i32(proj + PR_KIND) ~= KIND_STRAIGHT or u8(proj + PR_SKILL) ~= 0 then return false end
  local p = local_player()
  return p ~= 0 and i64(proj + PR_OWNER) == i64(p + C_ID)
end

local function proj_pos(proj)
  return units.to_blocks(i64(proj + PR_POS)), units.to_blocks(i64(proj + PR_POS + 8)), units.to_blocks(i64(proj + PR_POS + 16))
end

local function end_draw()
  if drawn then
    put_i32(drawn + PR_KIND, KIND_STRAIGHT)
    drawn = nil
  end
end

function M._flight_reset()
  arrow, current, drawn, released = nil, nil, nil, 0
  arrow_slot = nil
end

local function on_bar(ctx)
  local gc = u32(ctx.esp + BAR_CONTROLLER)
  if gc == 0 then return end
  local p = u32(gc + GC_PLAYER)
  if p == 0 or not handlers.armed(p) then return end
  local keys = ffi.cast("uint8_t*", gc)
  if keys[KEY_M1] ~= 0 and keys[KEY_M2] == 0 then keys[KEY_M2] = 1 end
end

local function on_release(ctx)
  local p = ctx.eax
  if p == 0 or not handlers.armed(p) then return end
  released = f32(p + C_CHARGED)
  put_u8(p + C_MODE, MODE_SHOT)
end

-- cube::World::bowShotSite: the game's arrow, complete and not yet in the World's list, becomes the mod's. The game aims it from
-- the shooter's own position at the aimed point, which sends it off at any angle when that point is near: the ability gives the
-- direction (a unit vector) instead, and the speed stays.
local function on_shot(ctx)
  local frame = ctx.ebp
  local creature = u32(frame - SHOT_CREATURE)
  if creature == 0 or u8(creature + C_MODE) ~= MODE_SHOT or not handlers.armed(creature) then return end
  local proj = frame - SHOT_PROJECTILE
  local charge = math.max(released, f32(creature + C_CHARGED), f32(creature + C_SPENT))
  released = 0
  local damage, speed, dx, dy, dz = handlers.on_arrow(creature, charge, proj_pos(proj))
  if not damage then return end
  put_i32(proj + PR_KIND, KIND_STRAIGHT)
  put_u8(proj + PR_SKILL, 0)
  local vx, vy, vz = f32(proj + PR_VEL), f32(proj + PR_VEL + 4), f32(proj + PR_VEL + 8)
  local pace = math.sqrt(vx * vx + vy * vy + vz * vz) * (speed or 1)
  if dx and pace > 0 then
    put_f32(proj + PR_VEL, dx * pace); put_f32(proj + PR_VEL + 4, dy * pace); put_f32(proj + PR_VEL + 8, dz * pace)
  elseif speed and speed ~= 1 then
    put_f32(proj + PR_VEL, vx * speed); put_f32(proj + PR_VEL + 4, vy * speed); put_f32(proj + PR_VEL + 8, vz * speed)
  end
  ctx.xmm[1].f32[0] = damage
  arrow = { hit = {}, age = -1, ms = 0, ended = false }
end

local function on_update(ctx)
  local proj = ctx.edi
  current = nil
  if proj == 0 or not is_ours(proj) or arrow.ended then return end
  current = proj
  arrow.age = i32(proj + PR_AGE)
  if handlers.on_flight then handlers.on_flight(proj_pos(proj)) end
end

local function on_stop(ctx)
  if current and ctx.edi == current then put_u8(ctx.ebp - STOP_FLAG, 0) end
end

local function on_surface(ctx)
  if not current or ctx.edi ~= current then return end
  put_i32(current + PR_KIND, KIND_ARROW)         -- the game ends it as its own arrow: a puff, no explosion, removal
  local x, y, z = proj_pos(current)
  current = nil
  if arrow then arrow.ended = true end
  if handlers.on_surface then handlers.on_surface(x, y, z) end
end

-- hitCreature takes 14 stack words: the target is the first, the projectile the 13th. A creature the arrow has hit is skipped.
-- Where `handlers.server_hits(world)` says the server makes the arrow's hits (a joined client),
-- the arrow makes none here: the call is skipped, so no hit goes to the server, and it is logged.
local function on_hit_creature(next, this, target, attacker, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
  if current and arrow and proj == current and target ~= 0 then
    local id = i64(target + C_ID)
    if arrow.hit[id] then return 0 end
    arrow.hit[id] = true
    if handlers.server_hits and handlers.server_hits(tonumber(ffi.cast("uint32_t", this))) then
      kyubu.info(("skills_unleashed: bow: the arrow reached creature %d: no hit here (the server makes it)"):format(id))
      return 0
    end
  end
  return next(this, target, attacker, a3, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
end
M._on_hit_creature = on_hit_creature            -- for the unit test

local function on_draw_kind(ctx)
  end_draw()                                     -- a draw whose end was not seen
  local proj = ctx.esi
  if proj == 0 or not arrow or not is_ours(proj) then return end
  put_i32(proj + PR_KIND, KIND_ARROW)
  drawn = proj
end

-- cube::GameController::projectileArrowModelSite: the game has taken its arrow model (EAX) for the draw of the projectile in ESI.
-- For the arrow of the mod it is the mod's model instead; every other arrow keeps the game's.
local function on_arrow_model(ctx)
  if not drawn or ctx.esi ~= drawn or not (loader and get_model) then return end
  local slot = arrow_model()
  if not slot then return end
  local model = tonumber(ffi.cast("uint32_t", get_model(loader, slot)))
  if model ~= 0 then ctx.eax = model end
end

local function on_draw_end()
  end_draw()
end

-- The draw record of draw_creature (EDI at the three sites below) holds the creature at its first word. True when that creature
-- holds a bow of the mod in either weapon slot.
local function holds_bow(record)
  if record == 0 then return false end
  local c = u32(record)
  return c ~= 0 and (is_marked(c + SLOT_RIGHT) or is_marked(c + SLOT_LEFT))
end

-- draw_creature_quiver_left_site / _right_site: the game has taken the quiver model (EAX) it draws on the back of a creature that
-- holds a bow. Nothing (0) for a creature that holds the bow of the mod: the game's own test then skips the quiver.
local function on_quiver(ctx)
  if holds_bow(ctx.edi) then ctx.eax = 0 end
end

-- Counts the arrow's life: call it every World step with the step's ms. When the arrow has ended, or `life_ms` has passed (the
-- game removes an arrow by itself), it is forgotten. Returns true while an arrow flies.
function M.poll(dt_ms, life_ms)
  if not arrow then return false end
  arrow.ms = arrow.ms + dt_ms
  if arrow.ended or arrow.ms >= life_ms then
    arrow, current = nil, nil
    return false
  end
  return true
end

function M.arrow_flying() return arrow ~= nil end

-- A world was entered: its id map has renumbered the model slots.
function M.world_entered()
  model_slot, arrow_slot = nil, nil
end

-- ---- install ---------------------------------------------------------------------------------------------------------------

local installed = false
local MID = {
  { "cube::GameController::abilityBarBuiltSite", on_bar },
  { "cube::GameController::bowReleaseSite", on_release },
  { "cube::World::bowShotSite", on_shot },
  { "cube::World::projectileUpdateSite", on_update },
  { "cube::World::projectileStopSite", on_stop },
  { "cube::World::projectileSurfaceSite", on_surface },
  { "cube::GameController::projectileDrawKindSite", on_draw_kind },
  { "cube::GameController::projectileArrowModelSite", on_arrow_model },
  { "cube::GameController::projectileDrawEndSite", on_draw_end },
  { "cube::World::chargeSoundSite", on_charge_sound },
  { SAVE_SITE, on_save_copy },
  { "draw_creature_quiver_left_site", on_quiver },
  { "draw_creature_quiver_right_site", on_quiver },
}
local SLOT_LOCK = "cube::GameController::equipmentSlotUnderCursor"
local HIT_CREATURE = "uint8_t(__thiscall*)(void*, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, "
  .. "uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t)"

-- Installs the sites once. `h`: armed(creature) -> true while that creature may charge and shoot the bow of the mod;
-- on_arrow(creature, charge, x, y, z) -> the arrow's damage, a factor of its speed and its direction (a unit vector dx, dy, dz, or
-- none to keep the game's aim), or nil to leave the game's arrow alone; x, y, z is where the arrow starts (blocks);
-- on_flight(x, y, z) at each World step of the arrow and on_surface(x, y, z) where it ends (blocks).
-- Returns true when every site is in place; a missing one is logged and its part of the bow is off.
function M.install(h)
  handlers = h
  if installed then return true end
  installed = true
  local all = true
  for _, site in ipairs(MID) do
    local id, err = kyubu.hook_mid(site[1], guarded(site[1], site[2]))
    if id then
      site_ok[site[1]] = true
    else
      all = false
      warn_once("site:" .. site[1], site[1] .. ": the hook failed (" .. tostring(err) .. ")")
    end
  end
  local id, err = kyubu.hook("cube::World::hitCreature", HIT_CREATURE, on_hit_creature)
  if not id then
    all = false
    warn_once("hit", "cube::World::hitCreature: the hook failed (" .. tostring(err) .. "): the arrow hits a creature more than once")
  end
  local lid, lerr = kyubu.hook(SLOT_LOCK, "void*(__thiscall*)(void*)", on_slot_under_cursor)
  if not lid then
    all = false
    warn_once("lock", SLOT_LOCK .. ": the hook failed (" .. tostring(lerr) .. "): the bow of light can be taken out of the hand")
  end
  if not M.look_on() then all = false end
  return all
end

return M
end

-- @module skills_unleashed.lib.combat (lib/combat.lua)
package.preload["skills_unleashed.lib.combat"] = function(...)
-- skills_unleashed.lib.combat: the game's own structures, through the FFI, for the abilities that hit or move creatures.
-- These are the combat calls proved in play, made reusable:
--   * the creatures are the nodes of the std::map at World+4 (mapping/atlas/core.md);
--   * a World step is the loader's sim.world_step event, once per step on Cube.exe and on
--     Server.exe; combat.defer(fn) runs fn in the next one, combat.every(fn) in each;
--   * a hit is kyubu.game.hit (cube::World::hitCreature with the stun and the push direction mapped), so kills give XP and threat
--     like any hit, armor or resistance applies, the damage number shows, and the stun is exactly the one asked for. It can only
--     be made inside a World step;
--   * a launch is a write to the target's velocity after the hit (a hit with a stun zeroes it);
--   * a taunt is a write into the monster's threat map (top_threat, set_threat): its combat AI attacks the largest entry.
-- A joined client does not apply hits on monsters (the server does): combat.can_hit() says so, and an ability then only moves.
-- Server.exe: the same file runs there. Its World has no local player (World+0xB8 = 0, not joined), so combat.is_server(world)
-- is true and step.player is nil. Server twins in mapping/server-0x51EA94D5: creature_damage, creature_map_slot 0x402B10,
-- creature_map_erase 0x40A1D0. It has no sound.
-- Needs Kyubu API 1.4 (sim.world_step and kyubu.game.hit); with an older loader no hit is made and nothing runs in a step.
-- Offsets: from the start of a Creature* (its entity data begins at +0x10).
-- The tree walk and the field reads are unit-tested against a fake World built in memory (the test process is 32 bit like the
-- game); the hit against a stand-in for kyubu.game.hit.
local ffi = require("ffi")
local bit = require("bit")
local units = require("skills_unleashed.lib.units")
local effect_log = require("skills_unleashed.lib.effect_log")

local M = {}

-- cube::Creature offsets (the data starts at +0x10)
local C_ID, C_POS, C_YAW, C_VEL, C_EXTRA, C_FLAGS = 0x08, 0x10, 0x30, 0x34, 0x4C, 0x5C
local C_HOSTILE, C_STUN, C_HP, C_MP = 0x60, 0x12C, 0x16C, 0x170
local C_MODE, C_MODE_TIME, C_CHARGED = 0x68, 0x6C, 0x144           -- cube::CreatureData.current_mode, mode_start_time (the time in the mode, ms) and charged_mp
local GC_KEY_ABILITY4 = 9                -- the key byte of the fourth ability: GameController + 4 + the bar's index 5 (probe fire-mage-charge)
local C_FLASH = 0x1184                       -- cube::Creature.hit_flash
local C_COOLDOWNS = 0x139C                   -- cube::Creature.ability_cooldowns: std::map<int ability id, int ms left>
local C_THREAT = 0x13A4                      -- cube::Creature.threat: std::map<uint64 attacker id, float threat>
local C_STEALTH = 0x1190                     -- cube::Creature.stealth: 0 to 1, the game's stealth (probe ninja-scan-skip)
local C_SCALE = 0x80                         -- cube::AppearanceData.scale: the hitbox, blocks; z is its height
local C_RAY = 0x160                          -- cube::CreatureData.ray_hit: the aim, 3 floats, blocks from the creature's position
local C_MAIN_HAND = 0xAA8                    -- cube::CreatureData.equipment[7]: the weapon the bar and the modes follow
local C_OFF_HAND = 0x990                     -- equipment[6], the other hand
local I_TYPE, I_SUB, TYPE_WEAPON = 0x00, 0x01, 3   -- cube::ItemData: type, sub_type (weapons: 3 dagger, 4 fist, 5 longsword, ...)
-- cube::World offsets
local W_JOINED, W_PLAYER = 0xB4, 0xB8
-- the nodes of the creature map: left, parent, right, color, isnil, then the key at +0x10 and the creature at +0x18
local N_LEFT, N_PARENT, N_RIGHT, N_ISNIL, N_KEY, N_CREATURE = 0x00, 0x04, 0x08, 0x0D, 0x10, 0x18
local N_VALUE = 0x18                     -- the value of a map of floats (a threat map) sits where the creature pointer does
local N_INT_VALUE = 0x14                 -- the value of a map from int to int (the cooldowns): it follows the 4-byte key
local MAX_NODES = 20000                      -- a guard against a corrupt tree
local FLAG_ON_GROUND = 1                     -- physics_flags bit 0
local FLAG_IN_WATER = 2                      -- physics_flags bit 1: in water (a swimming creature is never on the ground)

M.offsets = { id = C_ID, pos = C_POS, yaw = C_YAW, vel = C_VEL, extra = C_EXTRA, flags = C_FLAGS, hostile = C_HOSTILE,
  stun = C_STUN, hp = C_HP, mp = C_MP, cooldowns = C_COOLDOWNS, threat = C_THREAT, stealth = C_STEALTH, ray_hit = C_RAY, main_hand = C_MAIN_HAND, off_hand = C_OFF_HAND, joined = W_JOINED, player = W_PLAYER }

local function u8(a) return ffi.cast("uint8_t*", a)[0] end
local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function f32(a) return ffi.cast("float*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_f32(a, v) ffi.cast("float*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: combat: " .. text) end
end

local damage_stat_fn = nil                   -- the attacker's damage stat, __fastcall(cube::Creature*) -> float
local play_sound_fn = nil                    -- play_sound(GameController*, id, int64 pos[3]*, volume, pitch), thiscall, ret 0x10
local controller_at = nil                    -- the address of the global that holds the GameController*
local map_slot_fn = nil                    -- creature_map_slot, thiscall(std::map*, const int64_t* id) -> float* (inserts a missing id)
local map_erase_fn = nil                  -- creature_map_erase, thiscall(std::map*, void** out_next, void* node): erase(iterator), ret 8
local slot_key = ffi.new("int64_t[1]")
local erase_next = ffi.new("void*[1]")

local function loader_has_hit()
  local g = kyubu and kyubu.game
  return g ~= nil and g.hit ~= nil and g.creature_find ~= nil
end

-- Resolves the game functions. Returns true when a hit can be made (the loader has kyubu.game.hit).
function M.init()
  local d = kyubu.symbol("creature_damage")
  if d then damage_stat_fn = ffi.cast("float(__fastcall*)(void*)", d) end
  local m = kyubu.symbol("creature_map_slot")
  if m then map_slot_fn = ffi.cast("float*(__fastcall*)(void*, void*, const int64_t*)", m) end
  local e = kyubu.symbol("creature_map_erase")
  if e then map_erase_fn = ffi.cast("void*(__fastcall*)(void*, void*, void**, void*)", e) end
  local s = kyubu.symbol("play_sound")
  local g = kyubu.symbol("cube::game_controller")
  if s and g then
    play_sound_fn = ffi.cast("void(__fastcall*)(void*, void*, uint32_t, const void*, float, float)", s)
    controller_at = g
  end
  return loader_has_hit()
end

-- Calls fn(node) for every node of a std::map the game builds (in key order: a head node whose left is the first node). The
-- World's creature map is one, and so are the maps inside a creature (threat, +0x13A4). `map` is the address of the std::map
-- member, that is of the word that holds the head pointer.
local function each_node(map, fn)
  local head = u32(map)
  if head == 0 then return end
  local node, n = u32(head + N_LEFT), 0
  while node ~= head and n < MAX_NODES do
    fn(node)
    local right = u32(node + N_RIGHT)
    if u8(right + N_ISNIL) == 0 then
      node = right
      while true do
        local l = u32(node + N_LEFT)
        if u8(l + N_ISNIL) ~= 0 then break end
        node = l
      end
    else
      local p = u32(node + N_PARENT)
      while u8(p + N_ISNIL) == 0 and node == u32(p + N_RIGHT) do node = p; p = u32(node + N_PARENT) end
      node = p
    end
    n = n + 1
  end
end

-- Calls fn(creature_address) for every creature of the World, in id order (an in-order walk of the std::map at World+4).
function M.each_creature(world, fn)
  each_node(world + 4, function(node)
    local c = u32(node + N_CREATURE)
    if c ~= 0 then fn(c) end
  end)
end

-- ---- threat: what a creature's combat AI attacks (mapping/atlas/ai.md, "Target choice") ----------------------------------
-- The target of a monster is the key of the largest value in its threat map (cube::Creature::topThreat, 0x4451F0), looked up in
-- the World and kept while it exists. Writing a large value for an id makes the monster walk to that creature from any
-- distance and keep it, whatever else hurts it. The chase lowers the value by 0.9 each step, so a taunt writes it again each step.

-- The id with the largest threat on creature `c` and the value (a tie goes to the later key, as the game's walk does); 0, 0 when
-- the map is empty.
function M.top_threat(c)
  local best_id, best = 0, 0.0
  each_node(c + C_THREAT, function(node)
    local id, v = i64(node + N_KEY), f32(node + N_VALUE)
    if id ~= 0 and best <= v then best_id, best = id, v end
  end)
  return best_id, best
end

-- The node of creature `c`'s threat map that holds `id`, or nil.
local function threat_node(c, id)
  local found = nil
  each_node(c + C_THREAT, function(node)
    if i64(node + N_KEY) == id then found = node end
  end)
  return found
end

-- The threat creature `c` holds for `id`, 0 when it holds none.
function M.threat_of(c, id)
  local node = threat_node(c, id)
  return node and f32(node + N_VALUE) or 0.0
end

-- True when creature `c`'s threat map has an entry for `id`, whatever its value (the game inserts entries of 0 when it only
-- looks one up). set_threat on a creature without one inserts it.
function M.holds_threat(c, id) return threat_node(c, id) ~= nil end

-- Erases the entry creature `c` holds for `id` when its value is at most `at_most`, through the game's own erase so the map
-- stays a valid tree. Returns true when one was erased. An entry left in the map, even below 0, comes back as 0.01 (probe
-- ninja-scan-skip) and then makes `id` the monster's target from any distance; an erased one is gone until the game adds it.
function M.forget_threat(c, id, at_most)
  if not map_erase_fn then
    warn_once("erase", "creature_map_erase has no symbol: a dropped threat stays in the map")
    return false
  end
  local node = threat_node(c, id)
  if not node or f32(node + N_VALUE) > at_most then return false end
  map_erase_fn(ffi.cast("void*", c + C_THREAT), nil, erase_next, ffi.cast("void*", node))
  return true
end

-- Sets the threat creature `c` holds for `id` through the game's own map (creature_map_slot inserts the entry when it is
-- missing). Returns true, or false and the reason. Only the World that runs the monster decides: a joined client's copy of a
-- monster is not run there (the server picks its target), so the write does nothing useful on a client.
function M.set_threat(c, id, value)
  if not map_slot_fn then
    warn_once("slot", "creature_map_slot has no symbol: no threat can be written")
    return false, "no symbol"
  end
  slot_key[0] = id
  local slot = map_slot_fn(ffi.cast("void*", c + C_THREAT), nil, slot_key)
  if slot == nil then return false, "no slot" end
  slot[0] = value
  return true
end

-- Writes the milliseconds left of creature `c`'s cooldown for ability `number` (the game's own map: it counts every entry down
-- each step and refuses the ability while its entry is above 0). Only an entry the game has made is written: it makes one at the
-- ability's first step. Returns true when it was written.
function M.set_cooldown(c, number, ms)
  local done = false
  each_node(c + C_COOLDOWNS, function(node)
    if i32(node + N_KEY) == number then put_i32(node + N_INT_VALUE, ms); done = true end
  end)
  return done
end

-- A creature's position in blocks.
function M.position(c)
  return i64(c + C_POS) / units.BLOCK, i64(c + C_POS + 8) / units.BLOCK, i64(c + C_POS + 16) / units.BLOCK
end

-- Where the creature aims, in blocks: for the local player the point where the camera's ray meets the world, rewritten by the
-- game every frame (mapping/atlas/combat.md). Returns x, y, z, or nil when it holds nothing (all zero) or no number.
function M.aim(c)
  local rx, ry, rz = f32(c + C_RAY), f32(c + C_RAY + 4), f32(c + C_RAY + 8)
  if rx ~= rx or ry ~= ry or rz ~= rz then return nil end
  if rx == 0 and ry == 0 and rz == 0 then return nil end
  local x, y, z = M.position(c)
  return x + rx, y + ry, z + rz
end

function M.id(c) return i64(c + C_ID) end
function M.hp(c) return f32(c + C_HP) end
-- The mp (0 to 1; rage, focus or mana by the class), and a write of it.
function M.mp(c) return f32(c + C_MP) end
function M.set_mp(c, v) put_f32(c + C_MP, v) end
-- The mp a hold mode has reserved (the game's charge bar); a mod ability that charges grows and clears it itself.
function M.charged(c) return f32(c + C_CHARGED) end
function M.set_charged(c, v) put_f32(c + C_CHARGED, v) end
-- Writes the creature's time in its mode to 0. The loader reads the drop as a new activation (an `interrupted` end and a start),
-- and the bound clip plays from its beginning.
function M.restart_mode_time(c) put_i32(c + C_MODE_TIME, 0) end
function M.mode_time(c) return u32(c + C_MODE_TIME) end
function M.mode(c) return u8(c + C_MODE) end                        -- cube::CreatureData.current_mode
-- Whether the key of the fourth ability (key 4) is held now. False when the game cannot be asked.
function M.ability_key_down()
  if not controller_at then return false end
  local gc = u32(controller_at)
  if gc == 0 then return false end
  return u8(gc + GC_KEY_ABILITY4) ~= 0
end
function M.is_hostile(c) return u8(c + C_HOSTILE) == 1 end
function M.is_alive(c) return f32(c + C_HP) > 0 end
function M.is_enemy(c) return M.is_hostile(c) and M.is_alive(c) end
function M.on_ground(c) return bit.band(u32(c + C_FLAGS), FLAG_ON_GROUND) ~= 0 end
-- Resting on something: the ground or water, the pair the game's own jump checks.
function M.landed(c) return bit.band(u32(c + C_FLAGS), FLAG_ON_GROUND + FLAG_IN_WATER) ~= 0 end
function M.is_stunned(c) return i32(c + C_STUN) > 0 end
function M.yaw_deg(c) return f32(c + C_YAW) end

-- The height of a creature's hitbox in blocks (AppearanceData.scale z), 0 when it reads as nonsense. A creature's position is the
-- middle of its hitbox: a still slime of scale 0.8 rested 0.40 above the ground (probe trap-body), the player stands 0.9 above it.
local MAX_SIZE = 64
local function size(v)
  if v ~= v or v <= 0 or v > MAX_SIZE then return 0 end
  return v
end
function M.height(c) return size(f32(c + C_SCALE + 8)) end
-- Half the width of a creature's hitbox on the ground (the larger of AppearanceData.scale x and y, halved), 0 when nonsense.
function M.half_width(c) return math.max(size(f32(c + C_SCALE)), size(f32(c + C_SCALE + 4))) / 2 end

-- A creature as a table for lib.volume: { addr, id, x, y, z (blocks: the middle of its hitbox), feet (blocks: the bottom),
-- half_width (blocks), hp, stunned }.
function M.read(c)
  local x, y, z = M.position(c)
  return { addr = c, id = M.id(c), x = x, y = y, z = z, feet = z - M.height(c) / 2, half_width = M.half_width(c),
    hp = M.hp(c), stunned = M.is_stunned(c) }
end

-- The living hostile creatures of the World, as tables, `skip_addr` (the player) left out.
function M.enemies(world, skip_addr)
  local out = {}
  M.each_creature(world, function(c)
    if c ~= skip_addr and M.is_enemy(c) then out[#out + 1] = M.read(c) end
  end)
  return out
end

function M.player(world) return u32(world + W_PLAYER) end
-- True for the World of Server.exe: it runs no local player and is not joined to anything.
function M.is_server(world) return u32(world + W_PLAYER) == 0 and u8(world + W_JOINED) == 0 end

-- The address of the creature with `id` in the World's map, or nil.
function M.find(world, id)
  local found = nil
  M.each_creature(world, function(c) if i64(c + C_ID) == id then found = c end end)
  return found
end
function M.is_joined(world) return u8(world + W_JOINED) ~= 0 end

-- True when a hit can be made now; otherwise false and the reason (logged once).
function M.can_hit(world)
  if M.is_joined(world) then
    warn_once("joined", "a joined client does not apply hits on monsters: abilities only move")
    return false, "joined"
  end
  if not loader_has_hit() then
    warn_once("apply", "this Kyubu has no kyubu.game.hit (API 1.4): abilities only move")
    return false, "no loader hit"
  end
  return true
end

-- The attacker's damage stat (a positive number; 10 when the game says otherwise, logged once).
function M.damage_stat(player)
  local v = damage_stat_fn and damage_stat_fn(ffi.cast("void*", player)) or 0
  if v ~= v or v <= 0 then
    warn_once("stat", "the damage stat reads " .. tostring(v) .. ", using the default")
    v = 10
  end
  return v
end

-- One hit through the World's own path (kyubu.game.hit: cube::World::hitCreature), inside a World step (a deferred or every-step
-- function). It takes off the target's armor (its resistance when `magic`), applies the hit counter, shows the number and calls
-- applyHit; the stun is exactly `stun_ms` (0: the hit gives none and leaves the target's own stun as it is). `attacker_id` 0 or
-- nil: a hit with no attacker. `knock` {x, y, z} (blocks a second, x east, y north, z up) is the hit's direction: the game's applyHit
-- makes it the target's knockback (a tenth of it on a target already stunned by an earlier hit); nil: none. Returns true when the hit
-- landed (false: dodged, blocked, void, or refused, logged once).
function M.hit(attacker_id, target, damage, stun_ms, magic, knock)
  local g = kyubu.game
  local th, why = g.creature_find(M.id(target))
  if not th then
    warn_once("find:" .. tostring(why), "the target of a hit has no handle: " .. tostring(why))
    return false
  end
  local ah = nil
  if attacker_id and attacker_id ~= 0 then ah = g.creature_find(attacker_id) end   -- none: a hit with no attacker
  local landed, err = g.hit(ah, th, { damage = damage, stun_ms = stun_ms or 0, magic = magic == true, knock = knock })
  if landed == nil then warn_once("hit:" .. tostring(err), "kyubu.game.hit refused: " .. tostring(err)) end
  return landed == true
end

-- True when the loader flags creature `c` (an address) unstoppable (creature_set_flags): a boss that no
-- push, stun, snare or launch may move. False for any creature when the loader is older than API 1.3 or has no handle for it.
function M.unstoppable(c)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find) then return false end
  local h = g.creature_find(M.id(c))
  if not h then return false end
  local info = h:get()
  return info ~= nil and info.flags ~= nil and info.flags.unstoppable == true
end

-- The height of the bottom of creature `c`'s hitbox (an address), in blocks: its position less half the hitbox's height, both read by
-- the loader from their mapped fields (creature_state_get: `pos` and `box`, cube::AppearanceData.scale).
-- nil and why when the loader has no `box` (an older loader) or no handle for the creature.
function M.feet_z(c)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find and g.creature_state_get) then return nil, "this Kyubu has no creature_state_get" end
  local h, why = g.creature_find(M.id(c))
  if not h then return nil, why end
  local s, err = g.creature_state_get(h)
  if not s then return nil, err end
  if not s.box then return nil, "this Kyubu's creature_state has no box" end
  return s.pos.z / units.BLOCK - s.box.z / 2
end

-- ---- movement and stun through the loader -------------------------------------------------------------------------------------
-- The velocity, the knockback channel (extra_vel) and the stun are read and written by the loader at their mapped offsets
-- (creature_state_get and creature_state_set), never by an offset here. A write is allowed only on the side that owns the
-- creature: on Cube.exe the client side owns the local player alone, so the client VM may move its player and nothing else
-- (KY_E_SIDE, logged once). Single-player monsters are moved by the server VM (abilities/berserker.lua sends it the strike).

-- The loader's state of creature `c` (an address): { pos, velocity, knock, stun_ms, ... }, or nil and why.
function M.state(c)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find and g.creature_state_get) then return nil, "this Kyubu has no creature_state_get" end
  local h, why = g.creature_find(M.id(c))
  if not h then return nil, why end
  return g.creature_state_get(h)
end

-- Writes the keys of `t` (creature_state_set's: velocity = {x, y, z}, knock = {x, y, z}, stun_ms, ...; a vector's part left out
-- keeps its value) to creature `c`. Returns true, or false and why (logged once).
local function set_state(c, t)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find and g.creature_state_set) then
    warn_once("state_set", "this Kyubu has no creature_state_set: creatures are not moved")
    return false, "no creature_state_set"
  end
  local h, why = g.creature_find(M.id(c))
  if not h then return false, why end
  local ok, err = g.creature_state_set(h, t)
  if not ok then
    warn_once("state_set:" .. tostring(err), "creature_state_set refused: " .. tostring(err))
    return false, err
  end
  return true
end

-- Sets a creature's velocity (blocks per second; x east, y north, z up). Does nothing to an unstoppable creature (returns false).
function M.launch(c, vx, vy, vz)
  if M.unstoppable(c) then return false end
  return set_state(c, { velocity = { x = vx, y = vy, z = vz } })
end

-- A push through the game's knockback channel (it fades by itself): the forward hop of the player.
function M.push(c, ex, ey)
  if M.unstoppable(c) then return false end
  return set_state(c, { knock = { x = ex, y = ey } })
end

function M.set_vertical_velocity(c, vz)
  if M.unstoppable(c) then return false end
  return set_state(c, { velocity = { z = vz } })
end

-- Both at once (one loader call): the knockback channel's x and y, and the vertical velocity. The throw of a creature.
function M.throw(c, ex, ey, vz)
  if M.unstoppable(c) then return false end
  return set_state(c, { knock = { x = ex, y = ey }, velocity = { z = vz } })
end

-- Plays the game's sound `id` (a case of play_sound: 0 is hit.wav) at a place in blocks: the volume falls with the distance to
-- the camera, as for the game's own sounds. A call with no symbol does nothing (logged once). Other players do not hear it:
-- the game plays it on this client only. `volume` and `pitch` are 1 when not given.
local sound_pos = ffi.new("int64_t[3]")
function M.play_sound(id, x, y, z, volume, pitch)
  if not play_sound_fn then
    warn_once("sound", "play_sound or cube::game_controller has no symbol: no sounds")
    return false
  end
  local controller = u32(controller_at)
  if controller == 0 then return false end
  sound_pos[0], sound_pos[1], sound_pos[2] = units.to_units(x), units.to_units(y), units.to_units(z)
  play_sound_fn(ffi.cast("void*", controller), nil, id, sound_pos, volume or 1.0, pitch or 1.0)
  effect_log.note_blocks("sound", x, y, z, tostring(id))
  return true
end

-- Cancels a creature's walk: its horizontal velocity and its knockback channel are zero, so it stays where it stands.
-- Gravity is left alone. Call it every step to hold a creature; the game's own walk input may write it back (not proved).
function M.stand_still(c)
  return set_state(c, { velocity = { x = 0, y = 0 }, knock = { x = 0, y = 0 } })
end

-- Moves a creature on the ground plan to x, y in blocks; its height and its velocity are left alone.
function M.set_ground_position(c, x, y)
  local pos = ffi.cast("int64_t*", c + C_POS)
  pos[0], pos[1] = math.floor(units.to_units(x) + 0.5), math.floor(units.to_units(y) + 0.5)
end

-- The hit flash of the render (Creature + 0x1184, 0 to 1, eased to 0 by the World step): hitCreature sets it, applyHit does not.
function M.flash(c, v) put_f32(c + C_FLASH, v or 1.0) end

-- The game's stealth of creature `c` (0 to 1). Above 0 the creature is drawn in render's later pass (the pale stealth look) and the
-- combat AI's first scan finds it only nearer; the World step raises it with sneak or drains it each step (mapping/atlas/creatures.md
-- "Stealth"), so a mod that holds it writes it every step.
function M.stealth(c) return f32(c + C_STEALTH) end
function M.set_stealth(c, v) put_f32(c + C_STEALTH, v) end

-- The stun left on creature `c`, ms (at or below 0: none), read by the loader; 0 when it cannot be read.
function M.stun_time(c)
  local s = M.state(c)
  return s and s.stun_ms or 0
end

-- The weapon creature `c` holds: its sub_type (cube::ItemData +1: 3 dagger, 4 fist, 5 longsword, ...) from the main hand
-- (equipment slot 7, which the bar, the modes and the model follow), else from the other hand; nil when neither holds a weapon.
function M.weapon(c)
  for _, at in ipairs({ C_MAIN_HAND, C_OFF_HAND }) do
    if u8(c + at + I_TYPE) == TYPE_WEAPON then return u8(c + at + I_SUB) end
  end
  return nil
end

-- Keeps a creature stunned for at least `ms` (it cannot act): used while a creature is in the air.
function M.keep_stunned(c, ms)
  if M.stun_time(c) < ms then return set_state(c, { stun_ms = ms }) end
  return true
end

-- ---- running inside a World step ---------------------------------------------------------------------------------------
-- One source of World steps serves every ability: an ability calls defer(fn) from its on_step (or any callback), and fn(step) runs
-- in the next World step, with step = { world, player, dt, step_out, effects, server }. every(fn) registers fn to run in every step
-- (for effects that go on after the hit, such as a creature in the air). The source is the loader's sim.world_step event.
local deferred, every_step = {}, {}
local event_id = nil

local function run_step(step)
  local queue = deferred
  deferred = {}
  for _, fn in ipairs(queue) do
    local ok, err = pcall(fn, step)
    if not ok then warn_once("deferred:" .. tostring(err), "deferred call failed: " .. tostring(err)) end
  end
  for _, fn in ipairs(every_step) do
    local ok, err = pcall(fn, step)
    if not ok then warn_once("every:" .. tostring(err), "step call failed: " .. tostring(err)) end
  end
end

-- sim.world_step: one call per World step. step.player is the World's local player (nil on Server.exe).
local function on_world_step(ev)
  local world = ev.world
  if not world or world == 0 then return end
  local player = u32(world + W_PLAYER)
  run_step({ world = world, player = player ~= 0 and player or nil, dt = ev.dt, step_out = ev.step_out, effects = ev.effects,
    server = player == 0 or nil })
end
M._on_world_step = on_world_step             -- for the unit test

-- Subscribes to sim.world_step once. Returns true when it is in place; false (logged once) with a loader that lacks it.
function M.install_hook()
  if event_id then return true end
  local id, err = kyubu.on("sim.world_step", function(ev)
    local ok, e = pcall(on_world_step, ev)
    if not ok then warn_once("step:" .. tostring(e), "world step error: " .. tostring(e)) end
  end)
  if not id then
    warn_once("event", "sim.world_step is unavailable (" .. tostring(err) .. "): nothing runs in a World step")
    return false
  end
  event_id = id
  return true
end

-- ---- the hits a client sends (Server.exe) ---------------------------------------------------------------------------------
-- cube::World::receivedHitSite passes once for each hit a client sent, before applyHit; the hit is in the list node that the loop's
-- iterator ([EBP-0x2B20]) points at, 8 bytes in (the loop's own getter, 0x52EB90, is `[ecx] + 8`). A hit starts with the attacker's
-- id and the target's, then the damage (+0x10) and the stun (+0x18) of cube::Hit. filter_received_hits(fn): fn(attacker_id,
-- target_id) returns true to drop the hit, which keeps its place in the list but hurts for 0 and stuns for 0. For a client's hit
-- on a creature that the server decides for itself (the Sniper's arrow). A shortcut (a frame offset and an owner-wide filter)
-- where a mapped hit-cut site would be cleaner.
local RECV_ITER = 0x2B20
local recv_filters, recv_hook = {}, nil
local recv_dropped = 0

local function on_received(ctx)
  local node = u32(ctx.ebp - RECV_ITER)
  if node == 0 then return end
  local h = node + 8
  local attacker, target = i64(h), i64(h + 8)
  for _, fn in ipairs(recv_filters) do
    if fn(attacker, target) then
      local was = f32(h + 0x10)
      put_f32(h + 0x10, 0)
      put_i32(h + 0x18, 0)
      recv_dropped = recv_dropped + 1
      if kyubu and kyubu.info then
        kyubu.info(("skills_unleashed: server: dropped a hit of creature %d on %d (%.2f damage): the server decides"):format(attacker,
          target, was))
      end
      return
    end
  end
end
M._on_received = on_received                 -- for the unit test

function M.filter_received_hits(fn)
  recv_filters[#recv_filters + 1] = fn
  if recv_hook then return true end
  local id, err = kyubu.hook_mid("cube::World::receivedHitSite", function(ctx)
    local ok, e = pcall(on_received, ctx)
    if not ok then warn_once("recv:" .. tostring(e), "received-hit hook error: " .. tostring(e)) end
  end)
  if not id then
    warn_once("recv", "the received-hit hook failed: " .. tostring(err))
    return false
  end
  recv_hook = id
  return true
end

function M.defer(fn) deferred[#deferred + 1] = fn end
function M.every(fn) every_step[#every_step + 1] = fn end

-- Drops what is waiting (a new world, or an ability that ended early).
function M.reset() deferred = {} end

return M
end

-- @module skills_unleashed.lib.effect_log (lib/effect_log.lua)
package.preload["skills_unleashed.lib.effect_log"] = function(...)
-- skills_unleashed.lib.effect_log: one log line per effect and sound the mod starts, for tests that compare what two clients show
-- (kmap probe replay with a watcher). Off by default: the option `log_effects` (config.toml) turns it on, for instance with the
-- console command `config skills_unleashed log_effects true`. The line is
--   skills_unleashed: effect <kind> at <x> <y> <z>[ <extra>]
-- with the place in blocks, one decimal. It is read on every call (effects are few), so a change takes effect at once.
local M = {}

local UNITS_PER_BLOCK = 65536

local function on()
  local c = kyubu and kyubu.config
  if not c or type(c.get) ~= "function" then return false end
  local ok, v = pcall(c.get, "log_effects")
  return ok and v == true
end

-- True when the option log_effects is on (for other test logs of the mod).
function M.enabled() return on() end

-- `pos` is {x, y, z} in world units (lib/fx's positions), or nil. `extra` is appended as it is.
function M.note(kind, pos, extra)
  if not on() then return end
  local x, y, z = 0, 0, 0
  if pos then
    x, y, z = (pos[1] or 0) / UNITS_PER_BLOCK, (pos[2] or 0) / UNITS_PER_BLOCK, (pos[3] or 0) / UNITS_PER_BLOCK
  end
  kyubu.info(("skills_unleashed: effect %s at %.1f %.1f %.1f%s"):format(kind, x, y, z, extra and (" " .. extra) or ""))
end

-- The same line for a place already in blocks (a sound).
function M.note_blocks(kind, x, y, z, extra)
  if not on() then return end
  kyubu.info(("skills_unleashed: effect %s at %.1f %.1f %.1f%s"):format(kind, x or 0, y or 0, z or 0, extra and (" " .. extra) or ""))
end

return M
end

-- @module skills_unleashed.lib.link (lib/link.lua)
package.preload["skills_unleashed.lib.link"] = function(...)
-- skills_unleashed.lib.link: whether a joined game can carry the mod's messages, and the guard that turns the abilities off when
-- it cannot.
--
-- In a joined game every ability needs the channels both ways: the client tells the server what it cast (lib/ability_channel), and
-- the server tells every client what it did (lib/world_events). The loader carries channels only while the join gate is in force
-- (docs/sides-and-networking.md, "Joined games"); without it `channel.send` fails with KY_E_NO_REMOTE. Some abilities would then
-- still half-work from the mode the game syncs, others not at all. So the guard runs no ability without the link: on the client the
-- run is cancelled at its start and the player is told why; on Server.exe the server's copy is cancelled and nothing is applied.
--
-- The check is a real send (kind `hello`), since the loader gives no other way to ask. The gate is set once when the loader boots,
-- so one answer holds for the whole process. A single-player game needs no link: there it always passes.
local M = {}

M.PROBE = "hello"                                  -- the probe's kind; both channels' receivers ignore it
M.NO_REMOTE = "remote does not support channels"   -- the loader's text for KY_E_NO_REMOTE
local ABILITY_CHANNEL = "skills_unleashed:ability" -- lib/ability_channel's channel (client to server)
local WORLD_CHANNEL = "skills_unleashed:world"     -- lib/world_events' channel (server to clients)

local verdict = nil      -- nil until a probe answered; then true or false for the rest of the process
local warned = false
local notice = false     -- the client's notice window is open
local overlay = false    -- its render.overlay handler is registered

local function host()
  local h = kyubu.host and kyubu.host()
  return h or {}
end

-- One probe. Returns true or false, or nil when the answer says nothing about the link (any error but KY_E_NO_REMOTE).
local function probe(server)
  local ch = kyubu.channel
  if not ch then return false end
  local ok, err
  if server then
    ok, err = ch.send(WORLD_CHANNEL, ch.ALL_CLIENTS, { kind = M.PROBE })
  else
    ok, err = ch.send(ABILITY_CHANNEL, ch.SERVER, { kind = M.PROBE })
  end
  if ok then return true end
  if err == M.NO_REMOTE then return false end
  return nil
end

-- True when the abilities may run here: a single-player game, or a joined game whose channels work. On Server.exe call it only
-- while a joined player is in the game (an ability's on_start): with nobody to send to, the loader also answers KY_E_NO_REMOTE.
function M.ok()
  local h = host()
  local server = h.host == "server"
  -- Only two hosts have a joined game: a joined Cube.exe and a dedicated Server.exe.
  if h.mode ~= (server and "dedicated" or "remote_client") then return true end
  if verdict ~= nil then return verdict end
  local v = probe(server)
  if v == nil then return true end
  verdict = v
  if v then
    kyubu.info("skills_unleashed: link: the channels work: abilities are on")
  end
  return v
end

local function draw()
  if not notice then return end
  local visible, still_open = kyubu.ui.begin("SkillsUnleashed", true)
  if visible then
    kyubu.ui.text("SkillsUnleashed abilities are off on this server.")
    kyubu.ui.text("The mod cannot send its messages here: the join gate is not in force.")
    kyubu.ui.text("The client and the server must run the same Kyubu and the same mods (see the log).")
  end
  kyubu.ui.finish()
  if still_open == false then notice = false end
end

local function off(ctx) return ctx.state ~= nil and ctx.state.link_off end

local function refuse(ctx, id)
  if ctx.state then ctx.state.link_off = true end
  ctx:cancel()
  local server = host().host == "server"
  if not warned then
    warned = true
    kyubu.error(("skills_unleashed: link: no channels in this joined game (the join gate is not in force): %s"):format(
      server and "the server applies no SkillsUnleashed ability" or "SkillsUnleashed abilities are off"))
  end
  kyubu.info(("skills_unleashed: link: %s cancelled at its start (no channels)"):format(id))
  if server or not kyubu.ui then return end
  notice = true
  if not overlay then
    overlay = true
    kyubu.on("render.overlay", draw)
  end
end

-- Wraps the callbacks of ability definition `def` (for kyubu.ability.define): a run that starts without the link is cancelled,
-- and its on_step and on_end do nothing. `watch` is left alone: a bystander only draws what it is told or sees.
function M.guard(id, def)
  local on_start, on_step, on_end = def.on_start, def.on_step, def.on_end
  def.on_start = function(ctx)
    if not M.ok() then return refuse(ctx, id) end
    if on_start then return on_start(ctx) end
  end
  if on_step then
    def.on_step = function(ctx)
      if off(ctx) then return end
      return on_step(ctx)
    end
  end
  if on_end then
    def.on_end = function(ctx)
      if off(ctx) then return end
      return on_end(ctx)
    end
  end
  return def
end

M._reset = function() verdict, warned, notice = nil, false, false end   -- for the unit test
M._notice = function() return notice end

return M
end

-- @module skills_unleashed.lib.sites (lib/sites.lua)
package.preload["skills_unleashed.lib.sites"] = function(...)
-- skills_unleashed.lib.sites: mid-function hooks into the game's hit and draw code, for abilities that mark creatures. Each is a
-- mapped site (mapping/atlas/combat.md, creatures.md; probes taunt-target and taunt-visual) that a mod reaches through a callback:
--
--   sites.on_hit(fn)    cube::World::hitListSite, step_output_push_hit and cube::World::hitDamageSite: fn(attacker_id, victim_id,
--                       damage, hit_addr) -> a damage, or nil to leave it (hit_addr: the cube::Hit, for its other fields).
--                       The first two are where the damage number is read from (the
--                       normal path of hitCreature copies its Hit at the list site; its special paths push it), the damage
--                       site is what the hit subtracts (the hp fell by exactly the factor in the replay); a hit is cut once,
--                       at the first of them it reaches.
--   sites.on_tint(fn)   creature_draw_site: fn(creature) -> { r, g, b } or nil. The factors multiply the colour of the creature's
--                       draw (the game's own arguments: a vec4 at the pointer [ESP+0x14]); a green creature goes dark more than red.
--   sites.on_mark(want, slot_of)   stun_mark_gate_site and stun_mark_model_site: `want(creature)` true draws the stun's mark on
--                       that creature, with the model of table slot `slot_of()` (a model of the mod's own, from kyubu.model.add)
--                       in place of the stars. A creature that is stunned really has its mark swapped too.
--   sites.on_walk(fn)   cube::GameController::walkLockSite, walkLockEndSite and cube::World::lockOnWalkPenaltySite: fn(player)
--                       -> true keeps the player's full walk speed. While an ability runs (its mode time below its duration +
--                       200 ms) the game clears the player's "full speed" bit (data.flags 0x40), which halves the walk's cap,
--                       and sets lock-on, which cuts the cap again (to 0.5 at worst) when the walk points away from the facing
--                       (probe ability-walk-speed). A true keeps the bit the input gave and the cap whole; lock-on stays.
--   sites.on_scan(fn)   cube::CombatBehavior::targetScanSite: fn(creature) -> true keeps that creature out of the first-target
--                       scan of every monster with no target (the Ninja's true stealth; probe ninja-scan-skip).
--
-- A callback that fails is caught and logged once; the game's own code goes on. Nothing is installed until a callback is given, so
-- a mod that does not mark creatures costs nothing. Several abilities may give callbacks: they run in the order given.
-- Server.exe: on_hit and on_scan only (its twins of hitListSite, hitDamageSite and targetScanSite; its hitDamageSite applies the
-- hits the clients send too, so a player's hit on a monster is seen there).
-- Joined clients: the hit site is reached there only for hits on the player's own copy (mapping/atlas/combat.md), so a cut of the
-- damage a monster does to the local player works, and a cut of the player's damage to monsters does not.
local ffi = require("ffi")
local bit = require("bit")

local M = {}

local C_STUN, C_FLAGS = 0x12C, 0x124                           -- cube::CreatureData.stun_time and flags
local F_FULL_SPEED = 0x40
local GC_PLAYER = 0x8006D0                                    -- cube::GameController: the player
local EBP_CREATURE = 0x2B14                                   -- cube::World::update: the creature, at [EBP-0x2B14]
local H_ATTACKER, H_VICTIM, H_DAMAGE = 0x00, 0x08, 0x10        -- cube::Hit
local STACK_COLOUR = 0x14                                      -- [ESP+0x14]: the pointer to draw_creature's colour vec4
local STACK_MODELS = 0x10C                                     -- [ESP+0x10C] at the mark's model site: the ModelLoader*
local STUN_FLOOR = -3000                                       -- the mark is drawn while the stun time is above this

local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: sites: " .. text) end
end

-- Installs a mid hook by symbol name once; the callback is guarded. Returns true when it is in place.
local function install(name, fn)
  local id, err = kyubu.hook_mid(name, function(ctx)
    local ok, e = pcall(fn, ctx)
    if not ok then warn_once("run:" .. name .. tostring(e), name .. ": " .. tostring(e)) end
  end)
  if not id then
    warn_once("install:" .. name, name .. ": the hook failed (" .. tostring(err) .. "): its effect is off")
    return false
  end
  return true
end

-- ---- the hit: the list push and the damage site ----------------------------------------------------------------------------
-- hitCreature builds a cube::Hit on its stack, copies it into the step output's hit list (the damage numbers the game shows are
-- read from that copy) and then calls applyHit with the same Hit, which subtracts the damage at hitDamageSite. A cut made only at
-- the damage site changes the hp and leaves the number showing the old damage (30 shown, 4 taken).
-- The copy is made in two ways: the normal path (a monster's or a player's melee, a projectile) inserts inline, at
-- cube::World::hitListSite, with the Hit at ESP+0xC4; the special paths (hit types 3 and 5) call step_output_push_hit. The
-- hook on the push alone never runs for a monster's hit.
-- So the callbacks run at whichever of the two the hit reaches, where the copy and the Hit applyHit gets are still one object,
-- and the damage site skips a Hit already handled. A hit that reaches neither (a hit received from a server) is handled at
-- the damage site. Without the list site the number of a normal hit is not cut: the hp is right and the number is not.

local hit_listeners = {}
local hit_installed = false
local push_installed = false
local list_installed = false
local LIST_HIT = 0xC4                           -- hitListSite: the Hit is at ESP+0xC4
local handled = nil                             -- { addr =, attacker =, victim =, damage = } of the last Hit the push passed on

-- Runs the callbacks on the Hit at `hit` (an address): the damage is replaced by what they return. Returns attacker, victim and
-- the damage after.
local function run_hit_listeners(hit)
  local attacker, victim = i64(hit + H_ATTACKER), i64(hit + H_VICTIM)
  local damage = ffi.cast("float*", hit + H_DAMAGE)
  local was = damage[0]
  local now = was
  for _, fn in ipairs(hit_listeners) do
    local ok, out = pcall(fn, attacker, victim, now, hit)
    if ok and type(out) == "number" then now = out
    elseif not ok then warn_once("hit:" .. tostring(out), "a hit callback failed: " .. tostring(out)) end
  end
  if now ~= was then damage[0] = now end
  return attacker, victim, damage[0]
end

local function on_hit_site(ctx)
  local hit = ctx.ebx
  if hit == 0 then return end
  local h = handled
  if h and h.addr == hit then
    handled = nil
    if h.attacker == i64(hit + H_ATTACKER) and h.victim == i64(hit + H_VICTIM) and h.damage == ffi.cast("float*", hit + H_DAMAGE)[0] then
      return                                    -- the push cut it already: the number and the hp agree
    end
  end
  run_hit_listeners(hit)
end
M._on_hit_site = on_hit_site                    -- for the unit test

-- The mid hook of cube::World::hitListSite: the normal path's Hit is on the stack at ESP+0xC4.
local function on_list_site(ctx)
  local addr = ctx.esp + LIST_HIT
  local ok, attacker, victim, damage = pcall(run_hit_listeners, addr)
  if ok then handled = { addr = addr, attacker = attacker, victim = victim, damage = damage }
  else warn_once("list:" .. tostring(attacker), "the hit list site failed: " .. tostring(attacker)) end
end
M._on_list_site = on_list_site                  -- for the unit test

-- The hook of step_output_push_hit(this, const cube::Hit*), thiscall.
local function on_push(next, this, hit)
  if hit ~= nil then
    local addr = tonumber(ffi.cast("uint32_t", hit))
    if addr ~= 0 then
      local ok, attacker, victim, damage = pcall(run_hit_listeners, addr)
      if ok then handled = { addr = addr, attacker = attacker, victim = victim, damage = damage }
      else warn_once("push:" .. tostring(attacker), "the hit push failed: " .. tostring(attacker)) end
    end
  end
  return next(this, hit)
end
M._on_push = on_push                            -- for the unit test

function M.on_hit(fn)
  hit_listeners[#hit_listeners + 1] = fn
  if not hit_installed then hit_installed = install("cube::World::hitDamageSite", on_hit_site) end
  if not list_installed then list_installed = install("cube::World::hitListSite", on_list_site) end
  if not push_installed and kyubu.symbol("step_output_push_hit") then
    local id, err = kyubu.hook("step_output_push_hit", "void(__thiscall*)(void*, void*)", on_push)
    if id then push_installed = true
    else warn_once("push-install", "step_output_push_hit: the hook failed (" .. tostring(err) .. "): damage numbers show the uncut damage") end
  elseif not push_installed and not (kyubu.host and kyubu.host().host == "server") then   -- Server.exe shows no number
    warn_once("push-symbol", "step_output_push_hit has no symbol: the damage numbers show the uncut damage")
  end
  return hit_installed
end

-- ---- the draw site -----------------------------------------------------------------------------------------------------

local tint_listeners = {}
local tint_installed = false

local function on_tint_site(ctx)
  local creature = ctx.esi
  if creature == 0 then return end
  local colour = nil
  for _, fn in ipairs(tint_listeners) do
    local ok, f = pcall(fn, creature)
    if ok and type(f) == "table" then
      colour = colour or ffi.cast("float*", u32(ctx.esp + STACK_COLOUR))
      colour[0], colour[1], colour[2] = colour[0] * f[1], colour[1] * f[2], colour[2] * f[3]
    elseif not ok then
      warn_once("tint:" .. tostring(f), "a tint callback failed: " .. tostring(f))
    end
  end
end
M._on_tint_site = on_tint_site                  -- for the unit test

function M.on_tint(fn)
  tint_listeners[#tint_listeners + 1] = fn
  if not tint_installed then tint_installed = install("creature_draw_site", on_tint_site) end
  return tint_installed
end

-- ---- the stun's mark ---------------------------------------------------------------------------------------------------

local mark_wants = {}                           -- { want = fn, slot_of = fn } in the order given
local mark_installed = false
local get_model = nil                           -- ModelLoader::get(this, slot) -> Model*, thiscall
local faked, saved_stun = 0, 0                  -- the creature whose stun time is 1 for this draw, and what it held

local function wanted(creature)
  for _, w in ipairs(mark_wants) do
    local ok, yes = pcall(w.want, creature)
    if ok and yes then return w end
  end
  return nil
end

local function on_gate_site(ctx)
  local c = ctx.esi
  if c == 0 or i32(c + C_STUN) > STUN_FLOOR then return end     -- the game draws its own mark here: the model site swaps it
  if not wanted(c) then return end
  faked, saved_stun = c, i32(c + C_STUN)
  ffi.cast("int32_t*", c + C_STUN)[0] = 1
end
M._on_gate_site = on_gate_site                  -- for the unit test

local function on_model_site(ctx)
  local c = ctx.esi
  if faked ~= 0 then
    ffi.cast("int32_t*", faked + C_STUN)[0] = saved_stun
    faked = 0
  end
  if c == 0 or not get_model then return end
  local w = wanted(c)
  if not w then return end
  local models = u32(ctx.esp + STACK_MODELS)
  if models == 0 then return end
  local ok, slot = pcall(w.slot_of)
  if not ok or type(slot) ~= "number" then return end
  local m = get_model(ffi.cast("void*", models), nil, slot)
  if m ~= nil then ctx.eax = tonumber(ffi.cast("uint32_t", m)) end
end
M._on_model_site = on_model_site                -- for the unit test

-- `want(creature_addr)` -> true to draw the bolts there; `slot_of()` -> the model's table slot (read at each draw: the slot
-- is known only after the game is ready).
function M.on_mark(want, slot_of)
  mark_wants[#mark_wants + 1] = { want = want, slot_of = slot_of }
  if mark_installed then return true end
  local a = kyubu.symbol("ModelLoader::get")
  if not a then
    warn_once("get", "ModelLoader::get has no symbol: no mark")
    return false
  end
  get_model = ffi.cast("void*(__fastcall*)(void*, void*, int32_t)", a)
  -- the model site first: the gate fakes a stun that only the model site puts back, so the gate goes in only when that is there
  local model = install("stun_mark_model_site", on_model_site)
  local gate = model and install("stun_mark_gate_site", on_gate_site)
  mark_installed = gate and true or false
  return mark_installed
end

-- ---- the walk while an ability runs ----------------------------------------------------------------------------------------
-- The game clears the full-speed bit at walkLockSite only on its mode rule's path; the bit still holds what the frame's input
-- gave it (the slow-walk key and stamina decide it). When a callback wants the full walk, that value is put back at
-- walkLockEndSite, where every path joins, so the World steps after it keep the doubled cap. The penalty site is reached only
-- while lock-on is set and the walk points away from the facing: XMM0 holds the cap's factor (0.5 to 1), made 1 there.

-- After an ability ends the game may lock the walk of the mode that follows for its first 200 ms (its duration is 0); a callback
-- that keeps the walk through that lock asks for this long, with room to spare.
M.WALK_LOCK_AFTER_MS = 400

local walk_wants = {}
local walk_installed = false
local walk_player = 0                           -- the player seen at the last lock site
local walk_keep = 0                             -- the player whose full-speed bit goes back at the end site

local function walk_wanted(p)
  for _, fn in ipairs(walk_wants) do
    local ok, yes = pcall(fn, p)
    if ok and yes then return true end
    if not ok then warn_once("walk:" .. tostring(yes), "a walk callback failed: " .. tostring(yes)) end
  end
  return false
end

local function flags(c) return ffi.cast("uint16_t*", c + C_FLAGS) end

local function on_walk_lock(ctx)
  local p = u32(ctx.edi + GC_PLAYER)
  walk_player = p
  if p ~= 0 and bit.band(flags(p)[0], F_FULL_SPEED) ~= 0 and walk_wanted(p) then walk_keep = p end
end
M._on_walk_lock = on_walk_lock                  -- for the unit test

local function on_walk_end(ctx)
  if walk_keep == 0 then return end
  if walk_keep == u32(ctx.edi + GC_PLAYER) then flags(walk_keep)[0] = bit.bor(flags(walk_keep)[0], F_FULL_SPEED) end
  walk_keep = 0
end
M._on_walk_end = on_walk_end                    -- for the unit test

local function on_walk_penalty(ctx)
  local c = u32(ctx.ebp - EBP_CREATURE)
  if c == 0 or c ~= walk_player or not walk_wanted(c) then return end
  ctx.xmm[0].f32[0] = 1.0
end
M._on_walk_penalty = on_walk_penalty            -- for the unit test

function M.on_walk(fn)
  walk_wants[#walk_wants + 1] = fn
  if walk_installed then return true end
  -- the end site first: the lock site only notes a player that the end site gives the bit back to
  local done = install("cube::GameController::walkLockEndSite", on_walk_end)
  local lock = done and install("cube::GameController::walkLockSite", on_walk_lock)
  walk_installed = lock and true or false
  if walk_installed then install("cube::World::lockOnWalkPenaltySite", on_walk_penalty) end
  return walk_installed
end

-- ---- the AI's first-target scan ------------------------------------------------------------------------------------------
-- A monster with no target scans every creature for the nearest enemy in range (cube::CombatBehavior::update). At
-- cube::CombatBehavior::targetScanSite EBX is the candidate and XMM2 its squared distance; a huge XMM2 puts it out of range, so
-- the scan never picks it (probe ninja-scan-skip: every pass with the player skipped, five slimes with no target for 15 s).
-- It does not make a monster drop a target it has: that is its threat map (combat.set_threat).

local FAR = 1.0e30
local scan_wants = {}
local scan_installed = false

local function on_scan_site(ctx)
  local c = ctx.ebx
  if c == 0 then return end
  for _, fn in ipairs(scan_wants) do
    local ok, yes = pcall(fn, c)
    if ok and yes then
      ctx.xmm[2].f32[0] = FAR
      return
    end
    if not ok then warn_once("scan:" .. tostring(yes), "a scan callback failed: " .. tostring(yes)) end
  end
end
M._on_scan_site = on_scan_site                  -- for the unit test

-- sites.on_scan(fn): fn(creature) -> true keeps that creature out of every monster's first-target scan.
function M.on_scan(fn)
  scan_wants[#scan_wants + 1] = fn
  if scan_installed then return true end
  scan_installed = install("cube::CombatBehavior::targetScanSite", on_scan_site)
  return scan_installed
end

return M
end

-- @module skills_unleashed.lib.snare (lib/snare.lua)
package.preload["skills_unleashed.lib.snare"] = function(...)
-- skills_unleashed.lib.snare: the snare, shared by every ability that roots a creature (the Scout's trap, the Water Mage's chains:
-- a creature one of them holds cannot be snared by the other). A snared creature
--   * is rooted: the loader's KY_CREATURE_ROOTED flag (creature_set_flags). At the World's
--     AI tick its behaviour is not run and its mode is held at none; at its move step it does not walk and is not knocked back,
--     but may fall. The behaviour stays in place, so the creature goes on as before once the flag is cleared;
--   * keeps one pose: its draw record (Creature+0x1498, EDI at draw_creature_join_site) is saved at its first draw and its words
--     +0x10 to +0x4EC are written back at every later draw (client only);
--   * cannot be stunned: its stun timer is held under the mark's floor (-3000), and a hit on it has its stun, slow and push taken
--     out (cube::Hit +0x18, +0x1C, +0x38), so it still takes the damage (the hit hook is the client's);
--   * is drawn whitish: its draw colour times `tint` (overbright, as the probe's white_level 3; client only).
-- After a snare it cannot be snared again for `immune_ms`. The clock is the World steps' own (ms), so a pause stops it.
-- Who roots: the side that owns the creature. On Server.exe lib/snare runs in the server VM and sets the flag itself. In
-- single-player it runs in the client VM, which owns only the local player (KY_E_SIDE for a monster), so it sends
-- `skills_unleashed:snare { id, rooted }` to its own server VM over the loopback channel; serve() there sets the flag, and takes
-- the message only from KY_CONN_LOCAL_CLIENT, so a joined player (connections 2 to 11) cannot root anything with it. The flag then
-- takes hold at the server side's next update. A joined client never snares: its monsters are the server's.
-- What the clients see: on Server.exe each start and end is sent to every joined client on `skills_unleashed:world`
-- (lib/world_events) as `snare_on { id, ms, by }` and `snare_off { id, why }`. A joined client keeps those as `shown` snares: they
-- get the one pose and the tint, and the listeners of on_shown and on_end, but nothing is written to the creature (it is the
-- server's). The stun and the hold are the server's, and reach the client with the creature's own updates.
local ffi = require("ffi")
local combat = require("skills_unleashed.lib.combat")
local sites = require("skills_unleashed.lib.sites")
local world_events = require("skills_unleashed.lib.world_events")

local M = {}

M.CHANNEL = "skills_unleashed:snare"

local C_ID, C_STUN = 0x08, 0x12C
local REC_FIRST, REC_LAST = 0x10, 0x4F0         -- the draw record's words that are frozen
local H_STUN, H_SLOW, H_DIR = 0x18, 0x1C, 0x38  -- cube::Hit: stun ms, slow ms, the push direction (3 floats)
local STUN_FLOOR, STUN_HELD = -3000, -4000      -- the mark is drawn above the floor; a snared creature is held below it

local function u32(a) return ffi.cast("uint32_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_f32(a, v) ffi.cast("float*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end

local cfg = { immune_ms = 10000, tint = { 3, 3, 3 } }
local snared = {}                               -- id -> { ends (clock ms, nil: until released), released, snap }
local immune = {}                               -- id -> the clock until which it cannot be snared
local shown = {}                                -- a joined client: id -> { by, snap }, the server's snares as its events said
local clock = 0
local world_of = nil                            -- the World the tables belong to: a new World starts empty
local installed = false
local served = false
local ended_listeners = {}
local shown_listeners = {}

local warned = {}
local function warn_once(key, text)
  if warned[key] then return end
  warned[key] = true
  if kyubu and kyubu.warn then kyubu.warn("skills_unleashed: snare: " .. text) end
end

M._state = function() return snared, immune, clock, shown end   -- for the unit test

-- The numbers: { immune_ms, tint = { r, g, b } }. Any field left out keeps its value.
function M.configure(t)
  if t.immune_ms then cfg.immune_ms = t.immune_ms end
  if t.tint then cfg.tint = t.tint end
end

function M.is_snared(id) return snared[id] ~= nil or shown[id] ~= nil end
-- A creature the loader flags unstoppable (creature_set_flags) is never snared.
function M.unstoppable_id(id)
  local g = kyubu and kyubu.game
  if not (g and g.creature_find) then return false end
  local h = g.creature_find(id)
  local info = h and h:get()
  return info ~= nil and info.flags ~= nil and info.flags.unstoppable == true
end
function M.is_immune(id) return (immune[id] or 0) > clock end
function M.can_snare(id) return not M.is_snared(id) and not M.is_immune(id) and not M.unstoppable_id(id) end
function M.now() return clock end

-- fn(id, why) after a snare ended ("time", "released", "gone", "dead"), this side's own or one the server told of.
function M.on_end(fn) ended_listeners[#ended_listeners + 1] = fn end
-- A joined client: fn(id, by, ms) when the server tells of a snare it started (`by` the ability that set it, `ms` nil: until
-- released).
function M.on_shown(fn) shown_listeners[#shown_listeners + 1] = fn end

-- Server.exe tells its joined clients. Elsewhere nothing is sent: in single-player the client VM snares and draws itself.
local function tell(kind, fields)
  if kyubu.side ~= "server" then return end
  local ok, err = world_events.broadcast(kind, fields)
  if not ok and err ~= "no channels" then
    kyubu.info(("skills_unleashed: snare: %s of creature %d not sent: %s"):format(kind, fields.id, tostring(err)))
  end
end

-- Sets or clears the rooted flag of creature `id` on this side, keeping its other flags. Returns true, or false and why.
local function set_rooted(id, on)
  local g = kyubu.game
  if not (g and g.creature_find and g.creature_set_flags) then return false, "this Kyubu has no creature_set_flags" end
  local h, why = g.creature_find(id)
  if not h then return false, why end
  local info = h:get()
  local f = (info and info.flags) or {}
  local ok, err = g.creature_set_flags(h, { unstoppable = f.unstoppable == true, invulnerable = f.invulnerable == true,
    rooted = on == true })
  if not ok then return false, err end
  return true
end
M._set_rooted = set_rooted                      -- for the unit test

-- Roots or frees creature `id` through the side that owns it (see the top of this file).
local function root(id, on)
  if kyubu.side == "server" then return set_rooted(id, on) end
  local ch = kyubu.channel
  if not ch then return false, "this Kyubu has no channels" end
  local ok, err = ch.send(M.CHANNEL, ch.SERVER, { id = id, rooted = on == true })
  if not ok then return false, err end
  return true
end

-- The server VM's end of the loopback: roots or frees the creature the local client names.
local function on_message(conn, t)
  if conn ~= kyubu.channel.LOCAL_CLIENT then
    warn_once("conn:" .. tostring(conn), "a snare message from connection " .. tostring(conn) ..
      " was refused (only the local client)")
    return
  end
  if type(t) ~= "table" or type(t.id) ~= "number" then return end
  local ok, why = set_rooted(t.id, t.rooted == true)
  if not ok then warn_once("set:" .. tostring(why), "creature " .. t.id .. " could not be rooted: " .. tostring(why)) end
end
M._on_message = on_message                      -- for the unit test

-- Registers the loopback channel's handler on the server side (call it once from the server script, at lifecycle.register).
function M.serve()
  if served then return true end
  local ch = kyubu.channel
  if not ch then return false end
  local ok, err = ch.register(M.CHANNEL, function(conn, t)
    local fine, e = pcall(on_message, conn, t)
    if not fine then warn_once("msg:" .. tostring(e), "message error: " .. tostring(e)) end
  end)
  if not ok then
    warn_once("register", "the channel could not be registered (" .. tostring(err) .. "): single-player snares do not root")
    return false
  end
  served = true
  return true
end

-- Snares creature `c` (an address) for `ms` (nil: until release); `by` names the ability for the clients ("water_mage", "scout").
-- Returns true, or false and why.
function M.start(c, ms, by)
  local id = combat.id(c)
  if snared[id] then return false, "snared" end
  if M.is_immune(id) then return false, "immune" end
  if M.unstoppable_id(id) then return false, "unstoppable" end
  local ok, why = root(id, true)
  if not ok then
    warn_once("root:" .. tostring(why), "creature " .. id .. " is not snared: " .. tostring(why))
    return false, "no root"
  end
  local x, y, z = combat.position(c)
