  combat.throw(c, vx, vy, vz)
end

local function strike(step, owner_id, rank)
  local t = block
  local player = combat.find(step.world, owner_id)
  if not player or not combat.is_alive(player) then return end
  if not combat.can_hit(step.world) then return end
  local px, py, pz = combat.position(player)
  local facing = facing_of(player)
  local primary, others = logic.strike_targets(t, { x = px, y = py, z = pz }, facing, combat.enemies(step.world, player))
  if not primary then return end

  local at_strike, at_landing = logic.damage(t, combat.damage_stat(player))
  kyubu.info(("skills_unleashed: server: berserker: strike at rank %d, landing radius %.1f"):format(rank, logic.impact_radius(t, rank)))
  if hit(step, owner_id, primary, at_strike, t.strike_stun_ms) then
    local vx, vy, vz = logic.primary_launch(t, primary, facing)
    throw(primary.c.addr, vx, vy, vz)
    flying[primary.c.id] = {
      id = primary.c.id, owner = owner_id, world = step.world, rank = rank, landing_damage = at_landing,
      vx = vx, vy = vy, vz = vz, age_ms = 0, left_ground = false, no_stun = primary.c.stunned,
      x = primary.c.x, y = primary.c.y, z = primary.c.z, facing = facing,
    }
  end
  for _, entry in ipairs(others) do
    if hit(step, owner_id, entry, at_strike, t.strike_stun_ms) then
      local vx, vy, vz = logic.secondary_shove(t, entry, facing)
      throw(entry.c.addr, vx, vy, vz)
    end
  end
end

local function land(step, mark)
  local t = block
  local owner = combat.find(step.world, mark.owner)
  -- The thrown creature lies on the landing point, so its push follows the player's facing now, as on the client.
  local facing = owner and facing_of(owner) or mark.facing
  local origin = { x = mark.x, y = mark.y, z = mark.z }
  local hits = logic.impact_targets(t, mark.rank, origin, combat.enemies(step.world, owner), nil)
  for _, entry in ipairs(hits) do
    if hit(step, mark.owner, entry, mark.landing_damage, t.impact_stun_ms) then
      local vx, vy, vz = logic.impact_shove(t, entry, facing)
      throw(entry.c.addr, vx, vy, vz)
    end
  end
  kyubu.info(("skills_unleashed: server: berserker: landing hit %d creature(s)"):format(#hits))
end

-- Runs in every World step (combat.every): strikes what the local client sent (single-player), then moves each creature in the air
-- and lands it.
local function tick(step)
  if #pending > 0 then
    local ranks = {}
    for i, r in ipairs(pending) do ranks[i] = r; pending[i] = nil end
    local player = step.player
    if not player then
      warn_once("no player", "a strike from the local client in a World with no local player was dropped")
    else
      for _, rank in ipairs(ranks) do strike(step, combat.id(player), rank) end
    end
  end
  if next(flying) == nil then return end
  local found = {}
  combat.each_creature(step.world, function(c)
    local id = combat.id(c)
    if flying[id] then found[id] = c end
  end)
  for id, mark in pairs(flying) do
    if mark.world ~= step.world then
      flying[id] = nil
    else
      local c = found[id]
      local seen = { present = c ~= nil, alive = c ~= nil and combat.is_alive(c), grounded = c ~= nil and combat.landed(c) }
      if c then mark.x, mark.y, mark.z = combat.position(c) end
      local verdict = logic.fly(block, mark, step.dt, seen)
      if verdict == "fly" then
        if not mark.no_stun then combat.keep_stunned(c, block.air_stun_ms) end
        throw(c, mark.vx, mark.vy, mark.vz)
      elseif verdict ~= "gone" then
        flying[id] = nil
        land(step, mark)
      else
        flying[id] = nil
      end
    end
  end
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

local function on_start(ctx)
  setup()
  ctx.state.struck = false
  ctx.state.owner = owner_of(ctx)
end

local function on_step(ctx)
  local state = ctx.state
  state.owner = state.owner or owner_of(ctx)
  if state.struck or not state.owner or not logic.strike_due(block, ctx.elapsed_ms) then return end
  state.struck = true
  local owner, rank = state.owner, ctx.rank
  combat.defer(function(step) strike(step, owner, rank) end)
end

-- The loopback's server end: the local client's strike `{ rank }` (single-player only). Any other connection is refused.
local function on_message(conn, t)
  if conn ~= kyubu.channel.LOCAL_CLIENT then
    warn_once("conn:" .. tostring(conn), "a strike from connection " .. tostring(conn) .. " was refused (only the local client)")
    return
  end
  if type(t) ~= "table" or type(t.rank) ~= "number" or t.rank ~= t.rank then return end
  local max_rank = block and block.max_rank or 1
  local rank = math.max(1, math.min(max_rank, math.floor(t.rank)))
  setup()
  pending[#pending + 1] = rank
end
M._on_message = on_message

-- Registers the loopback handler (call once from the server script at lifecycle.register, on every host: a message comes only
-- in single-player). Needs the tuning block, so it reads it when define() has not run (single-player defines no server ability).
function M.serve()
  if served then return true end
  if not block then
    local t, why = tuning.get(SPEC)
    if not t then
      warn_once("tuning", "no tuning: " .. tostring(why))
      return false
    end
    block = t
  end
  local ch = kyubu.channel
  if not ch then return false end
  local ok, err = ch.register(M.CHANNEL, function(conn, t)
    local fine, e = pcall(on_message, conn, t)
    if not fine then warn_once("msg:" .. tostring(e), "message error: " .. tostring(e)) end
  end)
  if not ok then
    warn_once("register", "the channel could not be registered (" .. tostring(err) .. "): single-player strikes hit nothing")
    return false
  end
  served = true
  return true
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, link.guard(ID, {
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "warrior", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
  }))
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
end

M._tick, M._flying, M._strike, M._pending = tick, flying, strike, pending

return M
end

-- @module skills_unleashed.server.fire_mage (server/fire_mage.lua)
package.preload["skills_unleashed.server.fire_mage"] = function(...)
-- skills_unleashed.server.fire_mage: the server's Fire Circle (Mage, Fire Mage, slot 4). The client's version is abilities/fire_mage.lua;
-- the spot, the radius, the circle's life and its damage are the same logic (logic/fire_mage.lua) and the same numbers (lib/tuning),
-- so the two agree. The effects are only the hits: no particle, light, sound or clip.
--
-- The cast is the client's declaration: at the release clip's `cast` marker the joined client sends
-- `cast { charge, spot }` on skills_unleashed:ability (lib/ability_channel). The server takes it only inside a run it admitted, once a
-- run, with a new sequence number, and only when logic.check_cast passes it against the server's own copy of the player: the time its
-- run has lasted, the highest mp of that copy in the run, its place and its aim. A refused cast is logged and does nothing. The
-- ground under the spot is the server's own (lib/terrain, world_block); the radius and the damage are computed here.
--
-- The cooldown: the server's admission starts the full one at the run's start. A run that ends with no accepted cast (too little
-- charge, a cut-off charge, a refused cast, the player's death) gives it back, as the client does (logic.cooldown_after), through
-- kyubu.game.ability_cooldown_set, so a quick second try is not refused here.
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local link = require("skills_unleashed.lib.link")
local terrain = require("skills_unleashed.lib.terrain")
local channel = require("skills_unleashed.lib.ability_channel")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.fire_mage")

local M = {}

local ID = "skills_unleashed:fire_mage"
local SPEC = "fire_mage"

local block = nil
local circles = {}                -- { c = logic.new_circle, owner = id, world = World, damage = per tick }, also after the run
local runs = {}                   -- player id -> the state (ctx.state) of that player's run now
local last_run = {}               -- player id -> the client's run number of the last cast taken (a stale cast is refused)
local ready = false

local function facing_of(player)
  local x, y = units.facing(combat.yaw_deg(player))
  return { x = x, y = y }
end

local function place_of(player)
  local x, y, z = combat.position(player)
  return { x = x, y = y, z = z }
end

-- One tick of damage to every enemy in the circle, as the client's hurt: the World's own hit with no stun.
local function hurt(step, entry)
  if not combat.can_hit(step.world) then return end
  local owner = combat.find(step.world, entry.owner)
  local list = logic.targets(block, entry.c, combat.enemies(step.world, owner))
  for _, e in ipairs(list) do
    combat.hit(entry.owner, e.addr, entry.damage, 0, true)
    entry.c.hits = entry.c.hits + 1
  end
end

-- The circle of an accepted cast: the client's spot, on the ground the server's blocks give under it.
local function cast(step, player, owner_id, charge, spot_in, seed)
  local t = block
  local spot = { x = spot_in.x, y = spot_in.y, z = spot_in.z }
  spot.z = logic.find_ground(t, terrain.solid_fn(step.world), spot)
  local radius = logic.radius(t, charge)
  circles[#circles + 1] = { c = logic.new_circle(t, spot, radius, seed), owner = owner_id, world = step.world,
    damage = logic.damage(t, combat.damage_stat(player)) }
  kyubu.info(("skills_unleashed: server: fire_mage: cast at %.1f, %.1f, %.1f, charge %.2f, radius %.1f")
    :format(spot.x, spot.y, spot.z, charge, radius))
end

-- The server's own clock of each run (its World steps since the start: the mode time is the client's report) and the highest mp
-- its copy of the player had in it (the client spends the charge from it at the cast, maybe before the cast arrives).
local function run_step(step)
  for id, st in pairs(runs) do
    st.held_ms = st.held_ms + step.dt
    local player = combat.find(step.world, id)
    if player then
      local mp = combat.mp(player)
      if mp > st.mp then st.mp = mp end
    end
  end
end

-- Runs in every World step (combat.every): the runs' clocks, and the circles burn on, also after the run that cast them.
local function tick(step)
  run_step(step)
  for i = #circles, 1, -1 do
    local entry = circles[i]
    if entry.world ~= step.world then
      table.remove(circles, i)
    else
      local due, event, done = logic.circle_step(block, entry.c, step.dt)
      if event == "active" then
        kyubu.info(("skills_unleashed: server: fire_mage: the circle (radius %.1f) is active"):format(entry.c.radius))
      end
      for _ = 1, due do hurt(step, entry) end
      if done then
        kyubu.info(("skills_unleashed: server: fire_mage: the circle is over after %d hits"):format(entry.c.hits))
        table.remove(circles, i)
      end
    end
  end
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

-- The cooldown goes back to logic.cooldown_after's for a run with no cast (0), as on the client.
local function give_back(st, why)
  local e = st.end_info
  local ms = logic.cooldown_after(block, logic.ENDED_INTERRUPTED, e.rank or 1)
  local ok, err = kyubu.game.ability_cooldown_set(e.creature, e.number, ms)
  kyubu.info(("skills_unleashed: server: fire_mage: no cast (%s), the cooldown set to %d ms%s")
    :format(why, ms, ok and "" or (": " .. tostring(err))))
end

local function refuse(id, why)
  kyubu.info(("skills_unleashed: server: fire_mage: the cast of player %d was refused: %s"):format(id, why))
end

-- In the World step: the checks that need the server's copy of the player, then the cast.
local function take_cast(step, id, st, ev)
  st.pending = false
  local player = combat.find(step.world, id)
  local why = nil
  if not player or not combat.is_alive(player) then why = "the player is not there or is dead" end
  if not why then
    local ax, ay, az = combat.aim(player)
    local facts = { held_ms = st.held_ms, mp = math.max(st.mp, combat.mp(player)), from = place_of(player),
      aim = ax and { x = ax, y = ay, z = az } or nil, facing = facing_of(player) }
    local ok, reason = logic.check_cast(block, ev, facts)
    if not ok then why = reason end
  end
  if why then
    refuse(id, why)
    if st.ended then give_back(st, "refused") end
    return
  end
  st.cast = true
  last_run[id] = ev.run
  st.casts = (st.casts or 0) + 1
  cast(step, player, id, ev.charge, ev.spot, st.casts)
end

-- skills_unleashed:ability `cast` from player `id` (lib/ability_channel): the run and the sequence are checked here, the rest in the
-- next World step.
local function on_cast(id, ev)
  local st = runs[id]
  if not st or st.ended then return refuse(id, "no run of the Fire Mage is going on") end
  if st.cast or st.pending then return refuse(id, "the run has cast already") end
  if ev.seq <= st.seq then return refuse(id, ("sequence %d is not new"):format(ev.seq)) end
  st.seq = ev.seq
  if last_run[id] == ev.run then return refuse(id, ("client run %d has cast already"):format(ev.run)) end
  st.pending = true
  combat.defer(function(step) take_cast(step, id, st, ev) end)
end

local function on_start(ctx)
  setup()
  local st = ctx.state
  st.owner = owner_of(ctx)
  st.cast, st.pending, st.ended, st.held_ms, st.mp, st.seq = false, false, false, 0, 0, 0
  if st.owner then runs[st.owner] = st end
end

-- One step of the run: only the owner, when the start did not know it. The run's clock and mp are the World step's (run_step).
local function on_step(ctx)
  local st = ctx.state
  if st.owner then return end
  st.owner = owner_of(ctx)
  if st.owner then runs[st.owner] = st end
end

-- The run is over. With no cast the cooldown goes back (give_back); a cast that arrived in the run but waits for the World step
-- decides it there.
local function on_end(ctx)
  local st = ctx.state
  st.ended = true
  st.end_info = { creature = ctx.creature, number = ctx.number, rank = ctx.rank }
  if st.owner and runs[st.owner] == st then runs[st.owner] = nil end
  if ctx.reason == "gone" and st.owner then last_run[st.owner] = nil end
  if st.cast or st.pending then return end
  give_back(st, tostring(ctx.reason))
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, link.guard(ID, {
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "mage", specialization = SPEC },
    restarts = 1,                 -- the client's release writes its mode time 0: the same run here (the cast is the event, not this)
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  }))
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  channel.on("cast", on_cast)
end

M._tick, M._circles = tick, circles

return M
end

-- @module skills_unleashed.server.guardian (server/guardian.lua)
package.preload["skills_unleashed.server.guardian"] = function(...)
-- skills_unleashed.server.guardian: the server's Taunt (Warrior, Guardian, slot 4). The client's version is abilities/guardian.lua;
-- the target choice, the taunt's life and the damage cut are the same logic (logic/guardian.lua) and the same numbers (lib/tuning),
-- so the two agree. The effects are only the world's: the monster's threat map and the hits it deals. No ring, sound, tint or bolts.
--
-- The shout is the client's declaration: at its clip's `shout` marker the joined client sends `taunt { aim, from }` on
-- skills_unleashed:ability (lib/ability_channel): the aimed point and where the player stood. The server takes one a run, with a new
-- sequence number, inside a run it admitted, and only when logic.check_taunt passes it against the server's own copy of the player
-- (its place, its aim, its facing) and the time the run has lasted. A refused taunt is logged and taunts nothing. The target is the
-- server's pick (logic.pick_target from the event's `from` and `aim`, on the server's monsters and its own immunities).
--
-- The taunt is the server's: every World step the taunter's id is written with threat_value into the monster's threat map; at its end
-- the map gets back what it held. A taunted monster's hits on its taunter are cut at Server.exe's hitListSite twin (lib/sites on_hit),
-- before the hit goes into the step output, so the hit packet the joined client applies carries the cut damage: the client does not
-- cut again. A hit between the two, either way, is an engagement (the players' hits reach the server's hitDamageSite).
-- The start and the end are told to every joined client on skills_unleashed:world (lib/world_events): `taunt_on { target, by,
-- ms }`, `taunt_off { target, by, why }`; caster and bystanders draw the tint and the bolts from them.
--
-- Not here: the cooldown (the server's admission gives the full one at the run's start, as the client does).
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local link = require("skills_unleashed.lib.link")
local sites = require("skills_unleashed.lib.sites")
local channel = require("skills_unleashed.lib.ability_channel")
local events = require("skills_unleashed.lib.world_events")
local units = require("skills_unleashed.lib.units")
local roster = require("skills_unleashed.logic.roster")
local logic = require("skills_unleashed.logic.guardian")

local M = {}

local ID = "skills_unleashed:guardian"
local SPEC = "guardian"

local block = nil
local state = logic.new_state()   -- the taunts in force and the immunities, of every Guardian on this server
local state_world = nil
local runs = {}                   -- player id -> the state (ctx.state) of that player's run now
local last_run = {}               -- player id -> the client's run number of the last taunt taken (a stale taunt is refused)
local ready = false

local function refuse(id, why)
  kyubu.info(("skills_unleashed: server: guardian: the taunt of player %d was refused: %s"):format(id, why))
end

local function tell(kind, fields)
  local ok, err = events.broadcast(kind, fields)
  if not ok and err ~= "no channels" then
    kyubu.info(("skills_unleashed: server: guardian: %s not sent: %s"):format(kind, tostring(err)))
  end
end

local function reset_for(world)
  if world ~= state_world then
    state = logic.new_state()
    state_world = world
  end
end

-- The server's own clock of each run (its World steps since the start).
local function run_step(step)
  for _, st in pairs(runs) do st.held_ms = st.held_ms + step.dt end
end

-- Runs in every World step (combat.every): the runs' clocks; each taunt's threat is written again, the time runs, and a taunt that
-- ended gives the map back what it held.
local function tick(step)
  run_step(step)
  reset_for(step.world)
  if next(state.taunts) == nil and next(state.immune) == nil then return end
  local alive, found = {}, {}
  combat.each_creature(step.world, function(c)
    local id = combat.id(c)
    found[id] = c
    if combat.is_alive(c) then alive[id] = true end
  end)
  for _, e in ipairs(logic.step(block, state, step.dt, alive)) do
    local c = found[e.target]
    if c and alive[e.target] then combat.set_threat(c, e.by, logic.restore_value(block, e.prior)) end
    tell(logic.EVENT_TAUNT_OFF, { target = e.target, by = e.by, why = e.reason })
    local how = ""
    if e.reason == logic.ENDED_TAUNTER_GONE then how = found[e.by] and ", the player is dead" or ", the player left" end
    kyubu.info(("skills_unleashed: server: guardian: taunt of creature %d by player %d ended (%s%s)"):format(e.target, e.by,
      e.reason, how))
  end
  for id, taunt in pairs(state.taunts) do
    local c = found[id]
    if c then combat.set_threat(c, taunt.by, logic.threat_value(block)) end
  end
end

-- lib/sites on_hit: an engagement keeps the taunt; a taunted monster's hit on its taunter is cut.
local function on_hit(attacker, victim, damage)
  logic.on_hit(state, attacker, victim)
  local cut, was = logic.scale_damage(block, state, attacker, victim, damage)
  if not was then return nil end
  kyubu.info(("skills_unleashed: server: guardian: a hit of creature %d on player %d was cut, %.2f to %.2f"):format(attacker,
    victim, damage, cut))
  return cut
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
  sites.on_hit(on_hit)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

-- In the World step: the checks that need the server's copy of the player, then the taunt.
local function take_taunt(step, id, st, ev)
  st.pending = false
  if st.ended then return refuse(id, "the run is over") end
  local player = combat.find(step.world, id)
  if not player or not combat.is_alive(player) then return refuse(id, "the player is not there or is dead") end
  local x, y, z = combat.position(player)
  local ax, ay, az = combat.aim(player)
  local fx, fy = units.facing(combat.yaw_deg(player))
  local ok, why = logic.check_taunt(block, ev, { held_ms = st.held_ms, from = { x = x, y = y, z = z },
    aim = ax and { x = ax, y = ay, z = az } or nil, facing = { x = fx, y = fy } })
  if not ok then return refuse(id, why) end
  st.taunted = true
  last_run[id] = ev.run
  reset_for(step.world)
  local from = { x = ev.from.x, y = ev.from.y, z = ev.from.z }
  local aim = { x = ev.aim.x, y = ev.aim.y, z = ev.aim.z }
  local target = logic.pick_target(block, state, from, aim, combat.enemies(step.world, player))
  if not target then
    kyubu.info(("skills_unleashed: server: guardian: shout of player %d at %.1f, %.1f, %.1f: nobody taunted"):format(id,
      aim.x, aim.y, aim.z))
    return
  end
  local prior = combat.threat_of(target.addr, id)
  logic.start(block, state, st.rank, target.id, id, prior)
  combat.set_threat(target.addr, id, logic.threat_value(block))
  local ms = logic.duration_ms(block, st.rank)
  tell(logic.EVENT_TAUNT_ON, { target = target.id, by = id, ms = ms })
  kyubu.info(("skills_unleashed: server: guardian: taunt of creature %d by player %d, rank %d, %.0f s (%d ms into the run)")
    :format(target.id, id, st.rank, ms / units.MS_PER_S, st.held_ms))
end

-- skills_unleashed:ability `taunt` from player `id` (lib/ability_channel): the run and the sequence are checked here, the rest in
-- the next World step.
local function on_taunt(id, ev)
