  local st = ctx.state
  st.owner = owner_of(ctx)
  st.taunted, st.pending, st.ended, st.held_ms, st.seq, st.rank = false, false, false, 0, 0, ctx.rank or 1
  if st.owner then runs[st.owner] = st end
