  local solid = terrain.solid_fn(step.world)
  if solid and solid(trap.x, trap.y, trap.z) then trap.x, trap.y = from.x, from.y end   -- the hand is in a wall: drop it at the feet
  local feet = combat.feet_z(player)
  trap.ground = feet or (from.z - combat.height(player) / 2)
  trap.owner, trap.run = owner_id, run
  owners[trap.id] = { player = owner_id }
  for _, old in ipairs(logic.add(block, state, trap)) do drop(old, "a fourth trap") end
  tell("trap_thrown", { id = trap.id, owner = owner_id, run = run, x = trap.x, y = trap.y, z = trap.z, vx = trap.vx, vy = trap.vy,
    vz = trap.vz, yaw = trap.yaw, ground = trap.ground })
  kyubu.info(("skills_unleashed: server: scout: trap %d thrown from %.1f, %.1f, %.1f (yaw %.0f, feet z %.2f)%s"):format(trap.id, trap.x,
    trap.y, trap.z, trap.yaw, trap.ground, terrain.available() and "" or ", no ground lookup"))
end

-- The jaws close: the closest enemy takes the damage and the snare, the others half and a knock (the hit's direction).
local function close_on(step, trap)
  local t = block
  local own = owners[trap.id]
  local player = combat.find(step.world, own.player)
  if not player then
    tell("trap_closed", { id = trap.id, others = {} })
    return
  end
  local can, why = combat.can_hit(step.world)
  local v = logic.victims(t, trap, combat.enemies(step.world, player), snare.is_snared, snare.can_snare)
  local others = {}
  for i, e in ipairs(v.others) do others[i] = e.c.id end
  tell("trap_closed", { id = trap.id, target = v.target and v.target.c.id or nil, others = others })
  if not v.target then
    kyubu.info(("skills_unleashed: server: scout: trap %d closed on nobody"):format(trap.id))
    return
  end
  if not can then
    kyubu.info(("skills_unleashed: server: scout: trap %d closed on creature %d: no damage (%s)"):format(trap.id, v.target.c.id,
      tostring(why)))
    return
  end
  local full, part = logic.damage(t, combat.damage_stat(player))
  combat.hit(own.player, v.target.c.addr, full, 0)
  local snared = false
  if v.snare and combat.is_alive(v.target.c.addr) then
    snared = snare.start(v.target.c.addr, nil, SPEC)
    if snared then own.snared = v.target.c.id end
  end
  for _, e in ipairs(v.others) do
    local knock = nil
    if not snare.is_snared(e.c.id) and not combat.unstoppable(e.c.addr) then
      local kx, ky, kz = logic.knock(t, trap, e)
      knock = { kx, ky, kz }
    end
    combat.hit(own.player, e.c.addr, part, 0, false, knock)
  end
  kyubu.info(("skills_unleashed: server: scout: trap %d closed on creature %d (%.0f damage%s), %d other(s) took %.0f"):format(trap.id,
    v.target.c.id, full, snared and ", snared" or ", not snared", #v.others, part))
end

-- The server's own clock of each run (its World steps since the start), and the time since its end.
local function run_step(step)
  for id, st in pairs(runs) do
    if st.ended then
      st.after_ms = st.after_ms + step.dt
      if st.after_ms > block.throw_late_ms then runs[id] = nil end
    else
      st.held_ms = st.held_ms + step.dt
    end
  end
end

-- Runs in every World step (combat.every), after the snare's own step: each trap flies, arms, goes off, closes and fades.
local function tick(step)
  run_step(step)
  reset_for(step.world)
  if #state.traps == 0 then return end
  local t = block
  local solid = terrain.solid_fn(step.world)
  local enemies = {}
  local list = {}
  for i, tr in ipairs(state.traps) do list[i] = tr end
  for _, trap in ipairs(list) do
    if trap.phase == "flight" then
      if logic.fly(t, trap, step.dt, solid) then
        tell("trap_landed", { id = trap.id, x = trap.x, y = trap.y, z = trap.z })
        kyubu.info(("skills_unleashed: server: scout: trap %d landed at %.2f, %.2f, %.2f (%.2f below its throw's feet)"):format(trap.id,
          trap.x, trap.y, trap.z, trap.ground - trap.z))
      end
      trap.impact = nil
    else
      local from, was = trap.t, trap.phase
      local entered = logic.advance(t, trap, step.dt, t.open_ms)
      if was == "sprung" and from < t.hit_ms and trap.t >= t.hit_ms then close_on(step, trap) end
      if entered == "armed" then tell("trap_armed", { id = trap.id }) end
      if entered == "fading" then
        local own = owners[trap.id]
        if own and own.snared then snare.release(own.snared); own.snared = nil end
        tell("trap_fading", { id = trap.id })
      end
      if trap.phase == "gone" then
        drop(trap, was == "fading" and "faded" or "ended")
      elseif trap.phase == "armed" then
        local owner = owners[trap.id].player
        if enemies[owner] == nil then enemies[owner] = combat.enemies(step.world, combat.find(step.world, owner)) end
        if logic.should_trigger(t, trap, enemies[owner], snare.is_snared) then
          logic.spring(trap)
          tell("trap_sprung", { id = trap.id })
          kyubu.info(("skills_unleashed: server: scout: trap %d sprung"):format(trap.id))
        end
      end
    end
  end
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  snare.configure({ immune_ms = block.immune_ms })
  combat.every(snare.step)
  combat.every(tick)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

local function refuse(id, why)
  kyubu.info(("skills_unleashed: server: scout: the throw of player %d was refused: %s"):format(id, why))
end

-- In the World step: the checks that need the server's copy of the player, then the throw.
local function take_throw(step, id, st, ev)
  st.pending = false
  local player = combat.find(step.world, id)
  if not player or not combat.is_alive(player) then return refuse(id, "the player is not there or is dead") end
  local px, py, pz = combat.position(player)
  local ok, why = logic.check_throw(block, ev, { held_ms = st.held_ms, after_ms = st.ended and st.after_ms or nil,
    from = { x = px, y = py, z = pz }, yaw = combat.yaw_deg(player) })
  if not ok then return refuse(id, why) end
  st.thrown = true
  last_run[id] = ev.run
  throw(step, id, { x = ev.from.x, y = ev.from.y, z = ev.from.z }, ev.yaw, ev.run)
end

-- skills_unleashed:ability `throw` from player `id` (lib/ability_channel): the run and the sequence are checked here, the rest in the
-- next World step.
local function on_throw(id, ev)
  local st = runs[id]
  if not st then return refuse(id, "no run of the Scout is going on") end
  if st.thrown or st.pending then return refuse(id, "the run has thrown already") end
  if ev.seq <= st.seq then return refuse(id, ("sequence %d is not new"):format(ev.seq)) end
  st.seq = ev.seq
  if last_run[id] == ev.run then return refuse(id, ("client run %d has thrown already"):format(ev.run)) end
  st.pending = true
  combat.defer(function(step) take_throw(step, id, st, ev) end)
end

local function on_start(ctx)
  setup()
  local st = ctx.state
  st.owner = owner_of(ctx)
  st.thrown, st.pending, st.ended, st.held_ms, st.after_ms, st.seq = false, false, false, 0, 0, 0
  if st.owner then runs[st.owner] = st end
end

-- One step of the run: only the owner, when the start did not know it. The run's clock is the World step's (run_step).
local function on_step(ctx)
  local st = ctx.state
  if st.owner then return end
  st.owner = owner_of(ctx)
  if st.owner then runs[st.owner] = st end
end

-- The run is over: a throw may still come for throw_late_ms (run_step forgets the run then).
local function on_end(ctx)
  local st = ctx.state
  st.ended = true
  if ctx.reason == "gone" and st.owner then
    last_run[st.owner] = nil
    if runs[st.owner] == st then runs[st.owner] = nil end
  end
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, link.guard(ID, {
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "ranger", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
    on_end = on_end,
  }))
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
  channel.on("throw", on_throw)
end

M._tick, M._throw = tick, throw
M._state = function() return state end

return M
end

-- @module skills_unleashed.server.sniper (server/sniper.lua)
package.preload["skills_unleashed.server.sniper"] = function(...)
-- skills_unleashed.server.sniper: the server's Bow of Light (Ranger, Sniper, slot 4). The client's version is abilities/sniper.lua (the
-- bow in the hand, the charge on both mouse buttons, the straight arrow that goes through creatures); the rules are the same
-- (logic/sniper.lua, lib/tuning), so the damage is the same.
--
-- The input is the client's own shoot packet: the loader copies each projectile
-- packet a joined client sends (kyubu.game.shots) and the game still relays it to the other clients, who draw that arrow. At each World
-- step the server takes them. A packet of the bow of light (kind 1, not powered: lib/bow's arrow) from the player whose connection
-- sent it is checked (logic.check_shot: the bow held in a run the server admitted, the server's copy holding the marked bow, the start
-- near the server's copy, the heading inside a cone around the server's aim). An accepted one gets the server's damage
-- (logic.arrow_damage with the charge the game spent, the packet's own damage is never used) and is pushed into the World's
-- projectile list (kyubu.game.projectile_push). The World's projectile step flies it, stops it on the server's blocks and makes its
-- hits, with lib/bow's patches ported here: the stop is cleared after a hit, each creature is hit once, a block ends it as an arrow.
-- The client makes no hit of its own arrow (lib/bow, server_hits), so nothing is hit twice and no hit filter is needed.
--
-- The bow is in the hand when the server's copy of the player holds the marked bow (the client's swap at the clip's `catch`, sent with
-- the player's equipment), not after a copied clip time. The held time is the server's own clock, hold_ms and shot_late_ms.
-- Not seen in play: the caster sees no damage number of its own arrow (the game's hit names the caster as attacker, and a client skips
-- those); the game's step also gives the shooter mana for an unpowered arrow, on the server's copy, which the client's next update
-- overwrites.
local ffi = require("ffi")
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local link = require("skills_unleashed.lib.link")
local bow = require("skills_unleashed.lib.bow")
local units = require("skills_unleashed.lib.units")
local logic = require("skills_unleashed.logic.sniper")

local M = {}

local ID = "skills_unleashed:sniper"
local SPEC = "sniper"

-- cube::Projectile (mapping/types/combat.toml)
local PR_OWNER, PR_POS, PR_VEL, PR_DAMAGE, PR_CHARGE, PR_POWERED, PR_KIND, PR_AGE = 0x00, 0x18, 0x3C, 0x48, 0x54, 0x5C, 0x60, 0x68
local PR_SIZE = 0x70
local KIND_ARROW, KIND_STRAIGHT = 0, 1
local STOP_FLAG = 0x2B58                               -- below EBP at projectileStopSite (Server.exe's frame is Cube.exe's)
-- hitCreature as lib/bow hooks it (the World a pointer, every other word a number), but with the damage as a float, which this detour
-- replaces
local HIT_CREATURE = "uint8_t(__thiscall*)(void*, uint32_t, uint32_t, float, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, "
  .. "uint32_t, uint32_t, uint32_t, uint32_t, uint32_t, uint32_t)"

local block = nil
local server_block = nil           -- the block with the server's longer hold (hold_ms + shot_late_ms)
local owners = {}                  -- creature id -> { state = }
local flights = {}                 -- creature id -> { damage =, hit = { [id] = true }, age_ms =, ended = } of its arrow in the World
local owners_world = nil
local current = nil                -- the address of our arrow while the World's projectile loop is on it
local ready = false

local function u8(a) return ffi.cast("uint8_t*", a)[0] end
local function i32(a) return ffi.cast("int32_t*", a)[0] end
local function f32(a) return ffi.cast("float*", a)[0] end
local function i64(a) return tonumber(ffi.cast("int64_t*", a)[0]) end
local function put_u8(a, v) ffi.cast("uint8_t*", a)[0] = v end
local function put_i32(a, v) ffi.cast("int32_t*", a)[0] = v end

local function reset_for(world)
  if world == owners_world then return end
  if owners_world ~= nil then owners, flights, current = {}, {}, nil end   -- another World: the old one's players are gone
  owners_world = world
end

-- True when the creature holds the bow of light (lib/bow's mark) in either weapon slot.
local function holds_bow(c)
  return bow.is_marked(c + bow.offsets.slot_right) or bow.is_marked(c + bow.offsets.slot_left)
end

local function blocks3(p, at) return { x = units.to_blocks(i64(p + at)), y = units.to_blocks(i64(p + at + 8)), z = units.to_blocks(i64(p + at + 16)) } end
local function vec3(p, at) return { x = f32(p + at), y = f32(p + at + 4), z = f32(p + at + 8) } end

-- ---- the shot ----------------------------------------------------------------------------------------------------------------

local function refuse(id, why)
  kyubu.info(("skills_unleashed: server: sniper: creature %d: shot refused (%s)"):format(id, why))
end

-- One packet the loader copied. Returns nothing; an accepted shot is in the World's list and in `flights`.
local function take(world, shot)
  local data = shot.data
  if type(data) ~= "string" or #data ~= PR_SIZE then return end
  local buf = ffi.new("uint8_t[?]", PR_SIZE)
  ffi.copy(buf, data, PR_SIZE)
  local p = tonumber(ffi.cast("uint32_t", ffi.cast("void*", buf)))
  if i32(p + PR_KIND) ~= KIND_STRAIGHT or u8(p + PR_POWERED) ~= 0 then return end   -- a game arrow, not the bow of light's
  local id = i64(p + PR_OWNER)
  if shot.connection ~= id + 1 then return refuse(id, ("sent on connection %d, not the shooter's"):format(shot.connection)) end
  local o = owners[id]
  if not o then return refuse(id, "no run of the ability") end
  local player = combat.find(world, id)
  if not player then return refuse(id, "the shooter is not in the World") end
  local px, py, pz = combat.position(player)
  local ax, ay, az = combat.aim(player)
  local ok, why = logic.check_shot(block, {
    held = o.state.phase == logic.HELD, bow = holds_bow(player), from = blocks3(p, PR_POS), at = { x = px, y = py, z = pz },
    vel = vec3(p, PR_VEL), aim = ax and { x = ax, y = ay, z = az } or nil })
  if not ok then return refuse(id, why) end
  local charge = logic.charge_fraction(f32(p + PR_CHARGE))
  local damage = logic.arrow_damage(block, combat.damage_stat(player), charge)
  ffi.cast("float*", p + PR_DAMAGE)[0] = damage
  put_i32(p + PR_AGE, 0)
  local pushed, err = kyubu.game.projectile_push(ffi.string(buf, PR_SIZE))
  if not pushed then return refuse(id, "projectile_push: " .. tostring(err)) end
  logic.on_arrow(o.state, charge)
  flights[id] = { damage = damage, hit = {}, age_ms = 0, ended = false }
  local v = vec3(p, PR_VEL)
  kyubu.info(("skills_unleashed: server: sniper: creature %d shot an arrow: charge %.2f, damage %.1f, velocity %.1f, %.1f, %.1f")
    :format(id, charge, damage, v.x, v.y, v.z))
end

local function take_shots(world)
  local shots, err = kyubu.game.shots()
  if not shots then
    if not M._shots_warned then
      M._shots_warned = true
      kyubu.warn("skills_unleashed: server: sniper: kyubu.game.shots is unavailable (" .. tostring(err) .. "): no arrow is flown")
    end
    return
  end
  for _, shot in ipairs(shots) do take(world, shot) end
end

-- ---- the flight: lib/bow's patches, on the server's World ------------------------------------------------------------------

local function flight_of(proj)
  if i32(proj + PR_KIND) ~= KIND_STRAIGHT or u8(proj + PR_POWERED) ~= 0 then return nil end
  local f = flights[i64(proj + PR_OWNER)]
  if f and not f.ended then return f end
  return nil
end

local function on_update(ctx)
  current = nil
  if ctx.edi ~= 0 and flight_of(ctx.edi) then current = ctx.edi end
end

local function on_stop(ctx)
  if current and ctx.edi == current then put_u8(ctx.ebp - STOP_FLAG, 0) end
end

local function on_surface(ctx)
  if not current or ctx.edi ~= current then return end
  local f = flight_of(current)
  put_i32(current + PR_KIND, KIND_ARROW)          -- the game ends it as its own arrow: a puff, no explosion, removal
  local at = blocks3(current, PR_POS)
  current = nil
  if f then f.ended = true end
  kyubu.info(("skills_unleashed: server: sniper: arrow stopped on a block at %.1f, %.1f, %.1f"):format(at.x, at.y, at.z))
end

-- hitCreature: the target is the first stack word, the damage the third, the projectile the 13th. Our arrow hits each creature once,
-- for the server's damage.
local function on_hit_creature(next, this, target, attacker, damage, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
  if current and proj == current and target ~= 0 then
    local f = flight_of(current)
    if f then
      local id = i64(target + combat.offsets.id)
      if f.hit[id] then return 0 end
      f.hit[id] = true
      damage = f.damage
      kyubu.info(("skills_unleashed: server: sniper: arrow hit creature %d for %.1f"):format(id, damage))
    end
  end
  return next(this, target, attacker, damage, a4, a5, a6, a7, a8, a9, a10, a11, a12, proj, a14)
end
M._on_hit_creature = on_hit_creature

local SITES = {
  { "cube::World::projectileUpdateSite", on_update },
  { "cube::World::projectileStopSite", on_stop },
  { "cube::World::projectileSurfaceSite", on_surface },
}

local function install_flight()
  for _, site in ipairs(SITES) do
    local id, err = kyubu.hook_mid(site[1], function(ctx)
      local ok, e = pcall(site[2], ctx)
      if not ok then kyubu.warn("skills_unleashed: server: sniper: " .. site[1] .. ": " .. tostring(e)) end
    end)
    if not id then kyubu.warn("skills_unleashed: server: sniper: " .. site[1] .. ": the hook failed (" .. tostring(err) .. ")") end
  end
  local id, err = kyubu.hook("cube::World::hitCreature", HIT_CREATURE, on_hit_creature)
  if not id then
    kyubu.warn("skills_unleashed: server: sniper: cube::World::hitCreature: the hook failed (" .. tostring(err) .. "): the arrow hits a creature more than once, for the game's damage")
  end
end

-- ---- each World step -------------------------------------------------------------------------------------------------------

local function tick(step)
  reset_for(step.world)
  take_shots(step.world)
  for id, f in pairs(flights) do
    f.age_ms = f.age_ms + step.dt
    if f.ended or f.age_ms >= block.arrow_life_ms then flights[id] = nil end
  end
  for id, o in pairs(owners) do
    local player = combat.find(step.world, id)
    if not player then
      -- the player left (or the World lost it): its run and its arrow go
      logic.finish(o.state, logic.ENDED_DIED)
      owners[id], flights[id] = nil, nil
      kyubu.info(("skills_unleashed: server: sniper: creature %d left: its bow is gone"):format(id))
    else
      if o.state.phase == logic.SUMMON and holds_bow(player) and logic.on_catch(block, o.state) then
        kyubu.info(("skills_unleashed: server: sniper: creature %d holds the bow of light"):format(id))
      end
      local ended = logic.step(server_block, o.state, step.dt, { alive = combat.is_alive(player), charging = false, shooting = false })
      if ended then kyubu.info(("skills_unleashed: server: sniper: creature %d: the bow is gone (%s)"):format(id, ended)) end
    end
  end
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  combat.every(tick)
  install_flight()
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

local function on_start(ctx)
  setup()
  local id = owner_of(ctx)
  if not id then return end
  local o = owners[id] or {}
  o.state = logic.new_state()
  logic.begin(o.state, ctx.rank, 0)
  owners[id] = o
  ctx.state.owner = id
end

local function on_end(ctx)
  local id = ctx.state.owner or owner_of(ctx)
  local o = id and owners[id]
  if not o then return end
  local player = owners_world and combat.find(owners_world, id)
  if player and holds_bow(player) then logic.on_catch(block, o.state) end
  local over = logic.on_ability_end(o.state, ctx.reason)
  kyubu.info(("skills_unleashed: server: sniper: creature %d: the run ended (%s): %s"):format(id, tostring(ctx.reason),
    over and ("no bow (" .. over .. ")") or "the bow is held"))
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  server_block = setmetatable({ hold_ms = t.hold_ms + t.shot_late_ms }, { __index = t })
  local ok, err = kyubu.ability.define(ID, link.guard(ID, {
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "ranger", specialization = SPEC },
    on_start = on_start,
    on_end = on_end,
  }))
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
end

M._tick, M._take = tick, take
M._owners = function() return owners end
M._flights = function() return flights end

return M
end

-- @module skills_unleashed.server.water_mage (server/water_mage.lua)
package.preload["skills_unleashed.server.water_mage"] = function(...)
-- skills_unleashed.server.water_mage: the server's Chain of the Deep (Mage, Water Mage, slot 4). The client's version is
-- abilities/water_mage.lua; the ring, the reach and the snare are the same logic (logic/water_mage.lua, lib/snare) with the same
-- numbers (lib/tuning), so the two agree. The cast is time based (`cast_ms`, the clip's `cast` marker: the server reads no clip)
-- from the player's feet in the server's copy. The effects are only the snares: no particle, chains, light or sound.
--
-- The ring runs on after the run ends (as on the client), so the pulse keeps going until its ring has run out. A snared creature is
-- held by lib/snare's step on the server (combat.every), not by its hooks: the draw and tint hooks are the client's and are not
-- installed here. lib/snare tells the joined clients of each snare (snare_on and snare_off on `skills_unleashed:world`), and
-- their Water Mage draws the chains from those.
--
-- Not here: the cooldown (the server's admission gives the full one at the run's start, as the client does; nothing is given back:
-- the client gives none either, the cast is at the marker).
local tuning = require("skills_unleashed.lib.tuning")
local combat = require("skills_unleashed.lib.combat")
local link = require("skills_unleashed.lib.link")
local snare = require("skills_unleashed.lib.snare")
local logic = require("skills_unleashed.logic.water_mage")

local M = {}

local ID = "skills_unleashed:water_mage"
local SPEC = "water_mage"

local block = nil
local state = logic.new_state()
local state_world = nil
local ready = false

-- A new World starts without pulses.
local function reset_for(world)
  if world == state_world then return end
  state, state_world = logic.new_state(), world
end

-- The feet: the bottom of the hitbox, read by the loader from the mapped fields (combat.feet_z). nil and why without them.
local function feet_of(player)
  local x, y = combat.position(player)
  local z, why = combat.feet_z(player)
  if not z then return nil, why end
  return { x = x, y = y, z = z }
end

-- The pulse leaves the caster's feet, at the rank the run was started with.
local function cast(step, owner_id, rank)
  reset_for(step.world)
  local player = combat.find(step.world, owner_id)
  if not player or not combat.is_alive(player) then return end
  local feet, why = feet_of(player)
  if not feet then
    kyubu.warn("skills_unleashed: server: water_mage: no pulse, the feet are unknown: " .. tostring(why))
    return
  end
  local pulse = logic.new_pulse(state, feet, rank)
  logic.add(state, pulse)
  kyubu.info(("skills_unleashed: server: water_mage: pulse %d from %.1f, %.1f, %.1f (rank %d, snare %.1f s)"):format(pulse.id,
    pulse.x, pulse.y, pulse.z, pulse.rank, logic.snare_ms(block, pulse.rank) / 1000))
end

-- The enemies the ring reached this step are snared; a joined World never gets here (the server is never joined).
local function catch(pulse, caught)
  local length = logic.snare_ms(block, pulse.rank)
  for _, entry in ipairs(caught) do
    local e = entry.c
    if entry.snare and snare.start(e.addr, length, SPEC) then
      pulse.snared = pulse.snared + 1
      kyubu.info(("skills_unleashed: server: water_mage: creature %d snared at %.1f blocks for %.1f s"):format(e.id, entry.d,
        length / 1000))
    end
  end
end

-- Runs in every World step (combat.every), after the snare's own step (setup order): each pulse grows and catches.
local function tick(step)
  reset_for(step.world)
  if #state.pulses == 0 then return end
  local enemies = combat.enemies(step.world, nil)
  local list = {}
  for i, p in ipairs(state.pulses) do list[i] = p end
  for _, pulse in ipairs(list) do
    local caught, ring_done = logic.step(block, pulse, step.dt, enemies, snare.can_snare)
    catch(pulse, caught)
    if logic.over(pulse, ring_done) then
      logic.remove(state, pulse)
      kyubu.info(("skills_unleashed: server: water_mage: pulse %d is over: %d snared"):format(pulse.id, pulse.snared))
    end
  end
end

local function setup()
  if ready then return end
  ready = true
  combat.init()
  combat.install_hook()
  snare.configure({ immune_ms = block.immune_ms })
  combat.every(snare.step)
  combat.every(tick)
end

local function owner_of(ctx)
  local info = ctx.creature and ctx.creature:get()
  return info and info.id or nil
end

local function on_start(ctx)
  setup()
  local st = ctx.state
  st.owner = owner_of(ctx)
  st.rank = ctx.rank or 1
  st.cast = false
end

-- The cast is deferred into the World step: the pulse leaves at cast_ms after the start, from the player's feet then.
local function on_step(ctx)
  local st = ctx.state
  st.owner = st.owner or owner_of(ctx)
  if not st.owner or st.cast then return end
  if (ctx.elapsed_ms or 0) < block.cast_ms then return end
  st.cast = true
  local owner, rank = st.owner, st.rank
  combat.defer(function(step) cast(step, owner, rank) end)
end

function M.define()
  local t, why = tuning.get(SPEC)
  if not t then error(why) end
  block = t
  local ok, err = kyubu.ability.define(ID, link.guard(ID, {
    duration_ms = t.duration_ms,
    mp_cost = t.mp_cost,
    max_rank = t.max_rank,
    cooldown_ms = tuning.cooldown_fn(t),
    claim = { slot = tuning.SLOT, class = "mage", specialization = SPEC },
    on_start = on_start,
    on_step = on_step,
  }))
  if not ok then error("kyubu.ability.define: " .. tostring(err)) end
end

M._tick, M._cast = tick, cast
M._state = function() return state end

return M
end

require("skills_unleashed.server.main")
